class Validator:
    def __init__(self) -> None:
        self.failures: list[str] = []
        self.check_count = 0

    def check(self, condition: bool, message: str) -> None:
        self.check_count += 1
        if not condition:
            self.failures.append(message)

    def read_csv(self, name: str) -> list[dict[str, str]]:
        path = RESULTS / name
        with path.open(newline="") as handle:
            return list(csv.DictReader(handle))


def is_blank(value: object) -> bool:
    return value is None or str(value).strip() == ""


def as_float(row: dict[str, str], key: str) -> float:
    value = row.get(key, "")
    if value == "":
        return math.nan
    return float(value)


def rounded_ratio(num: float, den: float) -> str:
    return f"{num / den:.3f}x"


def validate_png(path: Path) -> tuple[bool, str]:
    data = path.read_bytes()
    if len(data) < 33:
        return False, "too small"
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        return False, "bad signature"
    if data[12:16] != b"IHDR":
        return False, "missing IHDR"
    width, height = struct.unpack(">II", data[16:24])
    if width <= 0 or height <= 0:
        return False, f"bad dimensions {width}x{height}"
    return True, f"{width}x{height}"


def validate_artifact_set(v: Validator) -> None:
    expected = set(EXPECTED_RESULTS)
    actual = {p.name for p in RESULTS.iterdir() if p.is_file()}
    v.check(actual == expected, f"result files differ: missing={sorted(expected - actual)} extra={sorted(actual - expected)}")
    for name in EXPECTED_RESULTS:
        path = RESULTS / name
        v.check(path.exists(), f"missing result file: {name}")
        if path.exists():
            v.check(path.stat().st_size > 0, f"empty result file: {name}")


def validate_file_formats(v: Validator) -> None:
    for name in EXPECTED_RESULTS:
        path = RESULTS / name
        if not path.exists():
            continue
        if name.endswith(".png"):
            ok, detail = validate_png(path)
            v.check(ok, f"invalid PNG {name}: {detail}")
        elif name.endswith(".csv"):
            rows = v.read_csv(name)
            v.check(rows, f"CSV has no data rows: {name}")
            expected_rows = EXPECTED_CSV_ROWS[name]
            v.check(len(rows) == expected_rows, f"{name} row count {len(rows)} != {expected_rows}")
        elif name.endswith(".json"):
            with path.open() as handle:
                json.load(handle)
        elif name.endswith(".md"):
            v.check("# v047" in path.read_text(), f"report title missing in {name}")


