def validate_endpoint_tfe_stage_functional_spec(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_functional_spec_audit.csv")
    by_block = {row["block"]: row for row in rows}
    required_blocks = {
        "translational_position_weak_defect",
        "rotational_lie_position_weak_defect",
        "translational_velocity_weak_defect",
        "angular_velocity_weak_defect",
        "newton_euler_weak_balance",
        "lower_pair_index3_weak_constraints",
        "smooth_and_sharp_h_sweep_gate",
    }
    v.check(required_blocks <= set(by_block), f"TFE stage-functional spec blocks missing: {sorted(required_blocks - set(by_block))}")
    counted = [row for row in rows if row["counts_toward_stage_budget"] == "True"]
    v.check(sum(int(row["total_rows"]) for row in counted) == 132, "TFE stage-functional row budget does not sum to 132")
    v.check(len(counted) == 6, "TFE stage-functional spec should have six counted row families")
    v.check(all(row["depends_on_gauss6_row_scaling"] == "False" for row in rows), "TFE stage-functional spec depends on Gauss6 row scaling")
    v.check(all(row["implemented_in_v047"] == "True" for row in counted), "TFE stage-functional counted rows are not implemented")
    v.check(all(row["h_sweep_present"] == "True" for row in counted), "TFE stage-functional counted rows lack h-sweep evidence")
    expected_totals = {
        "translational_position_weak_defect": 18,
        "rotational_lie_position_weak_defect": 18,
        "translational_velocity_weak_defect": 18,
        "angular_velocity_weak_defect": 18,
        "newton_euler_weak_balance": 36,
        "lower_pair_index3_weak_constraints": 24,
    }
    for block, expected in expected_totals.items():
        v.check(int(by_block[block]["total_rows"]) == expected, f"TFE stage-functional block {block} row count changed")
        v.check(by_block[block]["status"] == "implemented_equivalent_not_full_tfe", f"TFE stage-functional block {block} status changed")
    v.check(by_block["smooth_and_sharp_h_sweep_gate"]["status"] == "missing", "TFE stage-functional acceptance h-sweep gap not preserved")


def validate_endpoint_tfe_stage_functional_implementation(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_functional_implementation_audit.csv")
    by_case: dict[str, list[dict[str, str]]] = {}
    expected_blocks = {name for name, _, _ in [
        ("translational_position_weak_defect", 0, 6),
        ("rotational_lie_position_weak_defect", 6, 6),
        ("translational_velocity_weak_defect", 12, 6),
        ("angular_velocity_weak_defect", 18, 6),
        ("newton_euler_weak_balance", 24, 12),
        ("lower_pair_index3_weak_constraints", 36, 8),
    ]}
    expected_rows = {
        "translational_position_weak_defect": 18,
        "rotational_lie_position_weak_defect": 18,
        "translational_velocity_weak_defect": 18,
        "angular_velocity_weak_defect": 18,
        "newton_euler_weak_balance": 36,
        "lower_pair_index3_weak_constraints": 24,
    }
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        v.check(row["status"] == "implemented_equivalent_not_full_tfe", "TFE stage-functional implementation row status changed")
        v.check(row["independent_of_residual_black_box"] == "True", "TFE stage-functional implementation is not marked independent")
        v.check(row["quadrature_weighted"] == "True", "TFE stage-functional implementation is not quadrature weighted")
        v.check(row["h_sweep_present"] == "True", "TFE stage-functional implementation lacks h-sweep evidence")
        v.check(row["diagonal_equivalent_to_gauss6"] == "True", "TFE stage-functional implementation no longer records Gauss6 equivalence")
        v.check(row["full_tfe_stage_replacement"] == "False", "TFE stage-functional implementation overclaims full replacement")
        v.check(int(row["rows"]) == expected_rows[row["block"]], f"TFE stage-functional implementation row count changed for {row['block']}")
        v.check(as_float(row, "max_block_equivalence_norm") < 1.0e-10, "TFE stage-functional block equivalence too large")
        v.check(math.isfinite(as_float(row, "max_independent_block_residual_norm")), "TFE stage-functional independent residual norm not finite")
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"TFE stage-functional implementation cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        v.check({row["block"] for row in case_rows} == expected_blocks, f"TFE stage-functional implementation blocks mismatch for {case}")
        hs = sorted({as_float(row, "h") for row in case_rows})
        v.check(hs == [0.01, 0.02, 0.04], f"TFE stage-functional implementation h sweep mismatch for {case}: {hs}")


def validate_endpoint_tfe_stage_non_equivalent_probe(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_non_equivalent_probe_audit.csv")
    expected_blocks = {
        "translational_position_weak_defect",
        "rotational_lie_position_weak_defect",
        "translational_velocity_weak_defect",
        "angular_velocity_weak_defect",
        "newton_euler_weak_balance",
        "lower_pair_index3_weak_constraints",
    }
    expected_rows = {
        "translational_position_weak_defect": 18,
        "rotational_lie_position_weak_defect": 18,
        "translational_velocity_weak_defect": 18,
        "angular_velocity_weak_defect": 18,
        "newton_euler_weak_balance": 36,
        "lower_pair_index3_weak_constraints": 24,
    }
    by_case: dict[str, list[dict[str, str]]] = {}
    positive_probe = False
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        v.check(row["status"] == "non_equivalent_probe_not_solved", "non-equivalent stage probe row status changed")
        v.check(row["probe_source"] == "endpoint_position_velocity_boundary_correction", "non-equivalent stage probe source changed")
        v.check(row["h_sweep_present"] == "True", "non-equivalent stage probe lacks h-sweep evidence")
        v.check(row["non_equivalent_to_gauss6"] == "True", "non-equivalent stage probe is not marked non-equivalent")
        v.check(row["solved_as_residual"] == "False", "non-equivalent stage probe overclaims solved residual status")
        v.check(row["full_tfe_stage_replacement"] == "False", "non-equivalent stage probe overclaims full TFE replacement")
        v.check(row["block"] in expected_blocks, f"unexpected non-equivalent stage probe block {row['block']}")
        if row["block"] in expected_rows:
            v.check(int(row["rows"]) == expected_rows[row["block"]], f"non-equivalent stage probe row count changed for {row['block']}")
        probe_norm = as_float(row, "max_probe_block_norm")
        reference_norm = as_float(row, "max_reference_block_residual_norm")
        gap_norm = as_float(row, "max_non_equivalent_gap_norm")
        v.check(math.isfinite(probe_norm) and probe_norm >= 0.0, "non-equivalent stage probe norm is not finite")
        v.check(math.isfinite(reference_norm) and reference_norm >= 0.0, "non-equivalent stage probe reference residual norm is not finite")
        v.check(math.isfinite(gap_norm) and gap_norm >= 0.0, "non-equivalent stage probe gap norm is not finite")
        positive_probe = positive_probe or probe_norm > 0.0 or gap_norm > 0.0
    v.check(positive_probe, "non-equivalent stage probe is identically zero")
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"non-equivalent stage probe cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        v.check({row["block"] for row in case_rows} == expected_blocks, f"non-equivalent stage probe blocks mismatch for {case}")
        hs = sorted({as_float(row, "h") for row in case_rows})
        v.check(hs == [0.01, 0.02, 0.04], f"non-equivalent stage probe h sweep mismatch for {case}: {hs}")


def validate_endpoint_tfe_stage_probe_boundary_source(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_boundary_source_audit.csv")
    non_equiv = v.read_csv("cylindrical_chain_endpoint_tfe_stage_non_equivalent_probe_audit.csv")
    non_equiv_by_key = {
        (row["case"], row["h"], row["block"]): row
        for row in non_equiv
    }
    expected_source_dims = {
        "translational_position_weak_defect": 6,
        "rotational_lie_position_weak_defect": 6,
        "translational_velocity_weak_defect": 6,
        "angular_velocity_weak_defect": 6,
        "newton_euler_weak_balance": 12,
        "lower_pair_index3_weak_constraints": 8,
    }
    expected_blocks = set(expected_source_dims)
    by_case: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        block = row["block"]
        h = as_float(row, "h")
        source_dim = int(row["source_dim"])
        lifted_rows = int(row["lifted_rows"])
        source_norm = as_float(row, "source_norm")
        lifted_norm = as_float(row, "lifted_probe_norm")
        expected_lifted_norm = as_float(row, "expected_lifted_probe_norm")
        lift_error = as_float(row, "lift_reconstruction_error_norm")
        lift_ratio = as_float(row, "lift_norm_ratio")

        v.check(row["status"] == "stage_probe_boundary_source_lift_verified_not_full_tfe", "stage-probe boundary-source status changed")
        v.check(row["error_message"] == "", "stage-probe boundary-source unexpectedly has an error message")
        v.check(block in expected_blocks, f"unexpected stage-probe boundary-source block {block}")
        if block in expected_source_dims:
            v.check(source_dim == expected_source_dims[block], f"stage-probe boundary-source source dimension changed for {block}")
            v.check(lifted_rows == 3 * expected_source_dims[block], f"stage-probe boundary-source lifted rows changed for {block}")
        v.check(source_dim * 3 == lifted_rows, "stage-probe boundary-source lift is not three stages")
        v.check(math.isclose(as_float(row, "quadrature_weight_l2_norm"), math.sqrt(h), rel_tol=1.0e-12, abs_tol=1.0e-15), "stage-probe boundary-source quadrature L2 norm mismatch")
        v.check(math.isfinite(source_norm) and source_norm >= 0.0, "stage-probe boundary-source source norm invalid")
        v.check(math.isfinite(lifted_norm) and lifted_norm >= 0.0, "stage-probe boundary-source lifted norm invalid")
        v.check(math.isclose(expected_lifted_norm, math.sqrt(h) * source_norm, rel_tol=1.0e-10, abs_tol=1.0e-18), "stage-probe boundary-source expected lifted norm mismatch")
        v.check(math.isclose(lifted_norm, expected_lifted_norm, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe boundary-source lifted norm mismatch")
        v.check(lift_error < 1.0e-12, "stage-probe boundary-source lift reconstruction error too large")
        v.check(math.isclose(lift_ratio, 1.0, rel_tol=1.0e-9, abs_tol=1.0e-9), "stage-probe boundary-source lift ratio is not one")
        v.check(math.isfinite(as_float(row, "source_observed_order")), "stage-probe boundary-source source order is not finite")
        v.check(math.isfinite(as_float(row, "lifted_probe_observed_order")), "stage-probe boundary-source lifted order is not finite")
        v.check(math.isfinite(as_float(row, "reconstruction_error_observed_order")), "stage-probe boundary-source reconstruction order is not finite")
        v.check(row["h_sweep_present"] == "True", "stage-probe boundary-source lacks h-sweep evidence")
        v.check(row["source_is_endpoint_boundary_only"] == "True", "stage-probe boundary-source lost endpoint-boundary source marker")
        v.check(row["stage_equations_are_tfe_weighted"] == "True", "stage-probe boundary-source should use weighted stage equations")
        v.check(row["non_equivalent_to_gauss6"] == "True", "stage-probe boundary-source is not marked non-equivalent")
        v.check(row["solved_as_residual"] == "False", "stage-probe boundary-source overclaims solved residual")
        v.check(row["full_tfe_stage_replacement"] == "False", "stage-probe boundary-source overclaims full replacement")

        source = non_equiv_by_key.get((row["case"], row["h"], block))
        v.check(source is not None, f"stage-probe boundary-source missing non-equivalent source row for {(row['case'], row['h'], block)}")
        if source is not None:
            v.check(
                math.isclose(lifted_norm, as_float(source, "max_probe_block_norm"), rel_tol=1.0e-9, abs_tol=1.0e-18),
                f"stage-probe boundary-source lifted norm disagrees with non-equivalent probe for {(row['case'], row['h'], block)}",
            )
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"stage-probe boundary-source cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        v.check({row["block"] for row in case_rows} == expected_blocks, f"stage-probe boundary-source blocks mismatch for {case}")
        hs = sorted({as_float(row, "h") for row in case_rows})
        v.check(hs == [0.01, 0.02, 0.04], f"stage-probe boundary-source h sweep mismatch for {case}: {hs}")


def validate_endpoint_tfe_stage_probe_source_budget(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_source_budget_audit.csv")
    boundary_rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_boundary_source_audit.csv")
    expected_blocks = [
        "translational_position_weak_defect",
        "rotational_lie_position_weak_defect",
        "translational_velocity_weak_defect",
        "angular_velocity_weak_defect",
        "newton_euler_weak_balance",
        "lower_pair_index3_weak_constraints",
    ]
    boundary_by_key: dict[tuple[str, str], list[dict[str, str]]] = {}
    for row in boundary_rows:
        boundary_by_key.setdefault((row["case"], row["h"]), []).append(row)

    by_case: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        key = (row["case"], row["h"])
        block_rows = sorted(boundary_by_key.get(key, []), key=lambda item: expected_blocks.index(item["block"]))
        v.check(len(block_rows) == len(expected_blocks), f"stage-probe source-budget missing boundary rows for {key}")
        if not block_rows:
            continue
        h = as_float(row, "h")
        source_norms = [as_float(item, "source_norm") for item in block_rows]
        lifted_norms = [as_float(item, "lifted_probe_norm") for item in block_rows]
        source_l2 = math.sqrt(sum(value * value for value in source_norms))
        source_linf = max(source_norms)
        lifted_l2 = math.sqrt(sum(value * value for value in lifted_norms))
        lifted_linf = max(lifted_norms)
        expected_lifted = math.sqrt(h) * source_l2
        ratio = lifted_l2 / max(expected_lifted, 1.0e-300)
        max_lift_error = max(as_float(item, "lift_reconstruction_error_norm") for item in block_rows)
        max_ratio_deviation = max(abs(as_float(item, "lift_norm_ratio") - 1.0) for item in block_rows)
        dominant_source_block = block_rows[source_norms.index(source_linf)]["block"]
        dominant_lifted_block = block_rows[lifted_norms.index(lifted_linf)]["block"]

        v.check(row["status"] == "stage_probe_source_budget_prioritized_not_full_tfe", "stage-probe source-budget status changed")
        v.check(row["error_message"] == "", "stage-probe source-budget unexpectedly has an error message")
        v.check(int(row["block_count"]) == len(expected_blocks), "stage-probe source-budget block count changed")
        v.check(row["dominant_source_block"] == dominant_source_block, "stage-probe source-budget dominant source block mismatch")
        v.check(row["dominant_lifted_block"] == dominant_lifted_block, "stage-probe source-budget dominant lifted block mismatch")
        v.check(math.isclose(as_float(row, "source_l2_budget_norm"), source_l2, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget source L2 mismatch")
        v.check(math.isclose(as_float(row, "source_linf_budget_norm"), source_linf, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget source Linf mismatch")
        v.check(math.isclose(as_float(row, "lifted_l2_budget_norm"), lifted_l2, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget lifted L2 mismatch")
        v.check(math.isclose(as_float(row, "lifted_linf_budget_norm"), lifted_linf, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget lifted Linf mismatch")
        v.check(math.isclose(as_float(row, "expected_lifted_l2_budget_norm"), expected_lifted, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget expected lifted L2 mismatch")
        v.check(math.isclose(as_float(row, "lifted_budget_ratio"), ratio, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget ratio mismatch")
        v.check(math.isclose(as_float(row, "max_lift_reconstruction_error_norm"), max_lift_error, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget lift error mismatch")
        v.check(math.isclose(as_float(row, "max_lift_norm_ratio_deviation"), max_ratio_deviation, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget lift-ratio deviation mismatch")
        v.check(as_float(row, "max_lift_reconstruction_error_norm") < 1.0e-12, "stage-probe source-budget lift error too large")
        v.check(as_float(row, "max_lift_norm_ratio_deviation") < 1.0e-9, "stage-probe source-budget lift-ratio deviation too large")
        v.check(math.isclose(as_float(row, "dominant_source_fraction"), source_linf / max(source_l2, 1.0e-300), rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget dominant source fraction mismatch")
        v.check(math.isclose(as_float(row, "dominant_lifted_fraction"), lifted_linf / max(lifted_l2, 1.0e-300), rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe source-budget dominant lifted fraction mismatch")
        v.check(math.isfinite(as_float(row, "source_budget_observed_order")), "stage-probe source-budget source order is not finite")
        v.check(math.isfinite(as_float(row, "lifted_budget_observed_order")), "stage-probe source-budget lifted order is not finite")
        v.check(math.isfinite(as_float(row, "lifted_budget_ratio_error_observed_order")), "stage-probe source-budget ratio-error order is not finite")
        v.check(row["h_sweep_present"] == "True", "stage-probe source-budget lacks h-sweep evidence")
        v.check(row["source_is_endpoint_boundary_only"] == "True", "stage-probe source-budget lost endpoint-boundary marker")
        v.check(row["stage_equations_are_tfe_weighted"] == "True", "stage-probe source-budget should use weighted stage equations")
        v.check(row["non_equivalent_to_gauss6"] == "True", "stage-probe source-budget is not marked non-equivalent")
        v.check(row["solved_as_residual"] == "False", "stage-probe source-budget overclaims solved residual")
        v.check(row["full_tfe_stage_replacement"] == "False", "stage-probe source-budget overclaims full replacement")

    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"stage-probe source-budget cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        hs = sorted(as_float(row, "h") for row in case_rows)
        v.check(hs == [0.01, 0.02, 0.04], f"stage-probe source-budget h sweep mismatch for {case}: {hs}")


def validate_endpoint_tfe_stage_probe_dominant_source_split(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_dominant_source_split_audit.csv")
    boundary_rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_boundary_source_audit.csv")
    boundary_by_key = {
        (row["case"], row["h"], row["block"]): row
        for row in boundary_rows
    }
    expected_components = {
        "body0_translational_balance_source": ("0", "translational_balance"),
        "body0_rotational_balance_source": ("0", "rotational_balance"),
        "body1_translational_balance_source": ("1", "translational_balance"),
        "body1_rotational_balance_source": ("1", "rotational_balance"),
    }
    by_case_h: dict[tuple[str, str], list[dict[str, str]]] = {}
    by_case: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        by_case_h.setdefault((row["case"], row["h"]), []).append(row)
        h = as_float(row, "h")
        component = row["component"]
        component_source = as_float(row, "component_source_norm")
        component_lifted = as_float(row, "component_lifted_probe_norm")
        expected_lifted = as_float(row, "expected_component_lifted_probe_norm")
        lift_error = as_float(row, "component_lift_reconstruction_error_norm")
        ratio = as_float(row, "component_lift_norm_ratio")
        ratio_deviation = as_float(row, "component_lift_norm_ratio_deviation")
        source_fraction = as_float(row, "component_source_fraction_of_block")
        lifted_fraction = as_float(row, "component_lifted_fraction_of_block")
        block_source = as_float(row, "block_source_norm")
        block_lifted = as_float(row, "block_lifted_probe_norm")

        v.check(row["status"] == "stage_probe_dominant_source_split_prioritized_not_full_tfe", "dominant-source split status changed")
        v.check(row["error_message"] == "", "dominant-source split unexpectedly has an error message")
        v.check(row["block"] == "newton_euler_weak_balance", "dominant-source split block changed")
        v.check(component in expected_components, f"unexpected dominant-source split component {component}")
        if component in expected_components:
            body_index, component_kind = expected_components[component]
            v.check(row["body_index"] == body_index, f"dominant-source split body index mismatch for {component}")
            v.check(row["component_kind"] == component_kind, f"dominant-source split kind mismatch for {component}")
        v.check(int(row["component_source_dim"]) == 3, "dominant-source split component source dimension changed")
        v.check(int(row["component_lifted_rows"]) == 9, "dominant-source split component lifted rows changed")
        v.check(int(row["block_source_dim"]) == 12, "dominant-source split block source dimension changed")
        v.check(int(row["block_lifted_rows"]) == 36, "dominant-source split block lifted rows changed")
        v.check(math.isfinite(component_source) and component_source >= 0.0, "dominant-source split source norm invalid")
        v.check(math.isfinite(component_lifted) and component_lifted >= 0.0, "dominant-source split lifted norm invalid")
        v.check(math.isclose(expected_lifted, math.sqrt(h) * component_source, rel_tol=1.0e-10, abs_tol=1.0e-18), "dominant-source split expected lifted norm mismatch")
        v.check(math.isclose(component_lifted, expected_lifted, rel_tol=1.0e-9, abs_tol=1.0e-18), "dominant-source split lifted norm mismatch")
        v.check(lift_error < 1.0e-12, "dominant-source split lift reconstruction error too large")
        v.check(math.isclose(ratio, 1.0, rel_tol=1.0e-9, abs_tol=1.0e-9), "dominant-source split lift ratio not one")
        v.check(ratio_deviation < 1.0e-9, "dominant-source split lift-ratio deviation too large")
        v.check(0.0 <= source_fraction <= 1.0 + 1.0e-12, "dominant-source split source fraction out of range")
        v.check(0.0 <= lifted_fraction <= 1.0 + 1.0e-12, "dominant-source split lifted fraction out of range")
        v.check(math.isfinite(block_source) and block_source >= component_source, "dominant-source split block source norm invalid")
        v.check(math.isfinite(block_lifted) and block_lifted >= component_lifted, "dominant-source split block lifted norm invalid")
        v.check(math.isfinite(as_float(row, "component_source_observed_order")), "dominant-source split source order is not finite")
        v.check(math.isfinite(as_float(row, "component_lifted_probe_observed_order")), "dominant-source split lifted order is not finite")
        v.check(math.isfinite(as_float(row, "component_fraction_observed_order")), "dominant-source split fraction order is not finite")
        v.check(row["h_sweep_present"] == "True", "dominant-source split lacks h-sweep evidence")
        v.check(row["source_is_endpoint_boundary_only"] == "True", "dominant-source split lost endpoint-boundary marker")
        v.check(row["stage_equations_are_tfe_weighted"] == "True", "dominant-source split should use weighted stage equations")
        v.check(row["non_equivalent_to_gauss6"] == "True", "dominant-source split is not marked non-equivalent")
        v.check(row["solved_as_residual"] == "False", "dominant-source split overclaims solved residual")
        v.check(row["full_tfe_stage_replacement"] == "False", "dominant-source split overclaims full replacement")

        boundary = boundary_by_key.get((row["case"], row["h"], "newton_euler_weak_balance"))
        v.check(boundary is not None, f"dominant-source split missing boundary source row for {(row['case'], row['h'])}")
        if boundary is not None:
            v.check(math.isclose(block_source, as_float(boundary, "source_norm"), rel_tol=1.0e-9, abs_tol=1.0e-18), "dominant-source split block source mismatch")
            v.check(math.isclose(block_lifted, as_float(boundary, "lifted_probe_norm"), rel_tol=1.0e-9, abs_tol=1.0e-18), "dominant-source split block lifted mismatch")

    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"dominant-source split cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        hs = sorted({as_float(row, "h") for row in case_rows})
        v.check(hs == [0.01, 0.02, 0.04], f"dominant-source split h sweep mismatch for {case}: {hs}")
    for key, component_rows in by_case_h.items():
        v.check({row["component"] for row in component_rows} == set(expected_components), f"dominant-source split components mismatch for {key}")
        source_l2 = math.sqrt(sum(as_float(row, "component_source_norm") ** 2 for row in component_rows))
        lifted_l2 = math.sqrt(sum(as_float(row, "component_lifted_probe_norm") ** 2 for row in component_rows))
        block_source = as_float(component_rows[0], "block_source_norm")
        block_lifted = as_float(component_rows[0], "block_lifted_probe_norm")
        v.check(math.isclose(source_l2, block_source, rel_tol=1.0e-9, abs_tol=1.0e-18), f"dominant-source split component source L2 does not reconstruct block for {key}")
        v.check(math.isclose(lifted_l2, block_lifted, rel_tol=1.0e-9, abs_tol=1.0e-18), f"dominant-source split component lifted L2 does not reconstruct block for {key}")


def validate_endpoint_tfe_stage_probe_order(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_order_audit.csv")
    expected_blocks = {
        "translational_position_weak_defect",
        "rotational_lie_position_weak_defect",
        "translational_velocity_weak_defect",
        "angular_velocity_weak_defect",
        "newton_euler_weak_balance",
        "lower_pair_index3_weak_constraints",
    }
    expected_rows = {
        "translational_position_weak_defect": 18,
        "rotational_lie_position_weak_defect": 18,
        "translational_velocity_weak_defect": 18,
        "angular_velocity_weak_defect": 18,
        "newton_euler_weak_balance": 36,
        "lower_pair_index3_weak_constraints": 24,
    }
    by_case: dict[str, list[dict[str, str]]] = {}
    dominant_finest_count = 0
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        block = row["block"]
        v.check(row["status"] == "probe_order_quantified_not_full_tfe", "stage-probe order status changed")
        v.check(block in expected_blocks, f"unexpected stage-probe order block {block}")
        v.check(int(row["row_count"]) == 3, "stage-probe order row should aggregate three h values")
        v.check(row["h_values"] == "0.04,0.02,0.01", "stage-probe order h values changed")
        v.check(int(row["rows"]) == expected_rows[block], f"stage-probe order row count changed for {block}")
        v.check(row["non_equivalent_to_gauss6"] == "True", "stage-probe order no longer marks non-equivalence")
        v.check(row["solved_as_residual"] == "False", "stage-probe order overclaims solved status")
        v.check(row["full_tfe_stage_replacement"] == "False", "stage-probe order overclaims full TFE replacement")
        v.check(math.isfinite(as_float(row, "max_probe_block_norm")), "stage-probe order max probe norm not finite")
        v.check(math.isfinite(as_float(row, "max_non_equivalent_gap_norm")), "stage-probe order max gap not finite")
        v.check(math.isfinite(as_float(row, "non_equivalent_gap_observed_order")), "stage-probe order gap order not finite")
        v.check(as_float(row, "max_non_equivalent_gap_norm") >= 0.0, "stage-probe order gap is negative")
        dominant_finest_count += int(row["dominant_at_finest_h"] == "True")
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"stage-probe order cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        v.check({row["block"] for row in case_rows} == expected_blocks, f"stage-probe order blocks mismatch for {case}")
        v.check(sum(row["dominant_at_coarsest_h"] == "True" for row in case_rows) == 1, f"stage-probe order should have one coarse dominant block for {case}")
        v.check(sum(row["dominant_at_finest_h"] == "True" for row in case_rows) == 1, f"stage-probe order should have one fine dominant block for {case}")
    v.check(dominant_finest_count == 2, "stage-probe order should record one finest dominant block per case")


def validate_endpoint_tfe_stage_non_equivalent_solved_probe(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_non_equivalent_solved_probe_audit.csv")
    by_case: dict[str, list[dict[str, str]]] = {}
    positive_probe = False
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        v.check(row["status"] == "solved_non_equivalent_stage_probe_not_full_tfe", "solved non-equivalent stage probe status changed")
        v.check(row["stage_equations_are_tfe_weighted"] == "True", "solved non-equivalent stage probe should use weighted stage equations")
        v.check(row["non_equivalent_to_gauss6"] == "True", "solved non-equivalent stage probe is not marked non-equivalent")
        v.check(row["solved_as_residual"] == "True", "solved non-equivalent stage probe is not marked solved")
        v.check(row["full_tfe_stage_replacement"] == "False", "solved non-equivalent stage probe overclaims full TFE replacement")
        v.check(as_float(row, "max_solved_non_equivalent_probe_residual_norm") < 1.0e-9, "solved non-equivalent probe residual too large")
        v.check(as_float(row, "max_non_equivalent_stage_residual_norm") < 1.0e-9, "solved non-equivalent stage residual too large")
        v.check(as_float(row, "max_endpoint_position_constraint_norm") < 1.0e-10, "solved non-equivalent probe position constraint too large")
        v.check(as_float(row, "max_endpoint_velocity_constraint_norm") < 1.0e-10, "solved non-equivalent probe velocity constraint too large")
        v.check(math.isfinite(as_float(row, "position_observed_order")), "solved non-equivalent probe position order is not finite")
        v.check(math.isfinite(as_float(row, "velocity_observed_order")), "solved non-equivalent probe velocity order is not finite")
        probe_norm = as_float(row, "max_non_equivalent_stage_probe_norm")
        v.check(math.isfinite(probe_norm) and probe_norm >= 0.0, "solved non-equivalent probe norm is not finite")
        positive_probe = positive_probe or probe_norm > 0.0
    v.check(positive_probe, "solved non-equivalent stage probe is identically zero")
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"solved non-equivalent probe cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        hs = sorted(as_float(row, "h") for row in case_rows)
        v.check(hs == [0.01, 0.02, 0.04], f"solved non-equivalent probe h sweep mismatch for {case}: {hs}")


def validate_endpoint_tfe_stage_probe_homotopy(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_homotopy_audit.csv")
    by_case: dict[str, list[dict[str, str]]] = {}
    positive_beta_probe = False
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        beta = as_float(row, "beta")
        v.check(row["status"] == "stage_probe_homotopy_solved_not_full_tfe", "stage-probe homotopy status changed")
        v.check(row["h_sweep_present"] == "True", "stage-probe homotopy lacks h-sweep evidence")
        v.check(row["beta_path_present"] == "True", "stage-probe homotopy lacks beta-path evidence")
        v.check(row["stage_equations_are_tfe_weighted"] == "True", "stage-probe homotopy should use weighted stage equations")
        v.check(row["solved_as_residual"] == "True", "stage-probe homotopy is not marked solved")
        v.check(row["full_tfe_stage_replacement"] == "False", "stage-probe homotopy overclaims full TFE replacement")
        v.check(as_float(row, "max_homotopy_residual_norm") < 1.0e-9, "stage-probe homotopy residual too large")
        v.check(as_float(row, "max_homotopy_stage_residual_norm") < 1.0e-9, "stage-probe homotopy stage residual too large")
        v.check(as_float(row, "max_endpoint_position_constraint_norm") < 1.0e-10, "stage-probe homotopy position constraint too large")
        v.check(as_float(row, "max_endpoint_velocity_constraint_norm") < 1.0e-10, "stage-probe homotopy velocity constraint too large")
        probe_norm = as_float(row, "max_non_equivalent_stage_probe_norm")
        v.check(math.isfinite(probe_norm) and probe_norm >= 0.0, "stage-probe homotopy probe norm is not finite")
        if beta > 0.0:
            v.check(row["non_equivalent_to_gauss6"] == "True", "positive-beta homotopy row is not marked non-equivalent")
            positive_beta_probe = positive_beta_probe or probe_norm > 0.0
    v.check(positive_beta_probe, "stage-probe homotopy positive-beta probe is identically zero")
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"stage-probe homotopy cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        hs = sorted({as_float(row, "h") for row in case_rows})
        betas = sorted({as_float(row, "beta") for row in case_rows})
        v.check(hs == [0.01, 0.02, 0.04], f"stage-probe homotopy h sweep mismatch for {case}: {hs}")
        v.check(betas == [0.0, 0.25, 0.5, 0.75, 1.0], f"stage-probe homotopy beta path mismatch for {case}: {betas}")


