        v.check(row["non_equivalent_to_gauss6"] == "True", "stage-probe block activation should be non-equivalent")
        v.check(row["solved_as_residual"] == "True", "stage-probe block activation is not marked solved")
        v.check(row["full_tfe_stage_replacement"] == "False", "stage-probe block activation overclaims full TFE replacement")
        v.check(as_float(row, "max_block_activation_residual_norm") < 1.0e-9, "stage-probe block activation residual too large")
