def validate_endpoint_tfe_stage_probe_component_activation(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_component_activation_audit.csv")
    split_rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_dominant_source_split_audit.csv")
    target_component = "body0_translational_balance_source"
    split_by_case: dict[str, list[dict[str, str]]] = {}
    for row in split_rows:
        split_by_case.setdefault(row["case"], []).append(row)
    by_case: dict[str, list[dict[str, str]]] = {}
    positive_probe = False
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        h = as_float(row, "h")
        component_source = as_float(row, "component_source_norm")
        component_lifted = as_float(row, "component_lifted_probe_norm")
        expected_lifted = as_float(row, "expected_component_lifted_probe_norm")
        ratio = as_float(row, "component_lift_norm_ratio")
        ratio_deviation = as_float(row, "component_lift_norm_ratio_deviation")
        source_fraction = as_float(row, "component_source_fraction_of_block")
        lifted_fraction = as_float(row, "component_lifted_fraction_of_block")

        v.check(row["status"] == "stage_probe_component_activation_solved_not_full_tfe", "stage-probe component activation status changed")
        v.check(row["component"] == target_component, "stage-probe component activation target changed")
        v.check(row["block"] == "newton_euler_weak_balance", "stage-probe component activation block changed")
        v.check(row["body_index"] == "0", "stage-probe component activation body index changed")
        v.check(row["component_kind"] == "translational_balance", "stage-probe component activation kind changed")
        v.check(int(row["rows"]) == 9, "stage-probe component activation row count changed")
        v.check(int(row["component_source_dim"]) == 3, "stage-probe component activation source dimension changed")
        v.check(int(row["component_lifted_rows"]) == 9, "stage-probe component activation lifted rows changed")
        v.check(row["h_sweep_present"] == "True", "stage-probe component activation lacks h-sweep evidence")
        v.check(row["component_isolated"] == "True", "stage-probe component activation is not isolated")
        v.check(row["target_component_is_dominant"] == "True", "stage-probe component activation lost dominant-source link")
        v.check(row["source_is_endpoint_boundary_only"] == "True", "stage-probe component activation lost endpoint-boundary marker")
        v.check(row["stage_equations_are_tfe_weighted"] == "True", "stage-probe component activation should use weighted stage rows")
        v.check(row["non_equivalent_to_gauss6"] == "True", "stage-probe component activation should be non-equivalent")
        v.check(row["solved_as_residual"] == "True", "stage-probe component activation is not marked solved")
        v.check(row["full_tfe_stage_replacement"] == "False", "stage-probe component activation overclaims full TFE replacement")
        v.check(math.isfinite(component_source) and component_source >= 0.0, "stage-probe component activation source norm is invalid")
        v.check(math.isfinite(component_lifted) and component_lifted >= 0.0, "stage-probe component activation lifted norm is invalid")
        v.check(math.isclose(expected_lifted, math.sqrt(h) * component_source, rel_tol=1.0e-10, abs_tol=1.0e-18), "stage-probe component activation expected lift mismatch")
        v.check(math.isclose(component_lifted, expected_lifted, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe component activation lifted norm mismatch")
        v.check(math.isclose(ratio, 1.0, rel_tol=1.0e-9, abs_tol=1.0e-9), "stage-probe component activation lift ratio not one")
        v.check(ratio_deviation < 1.0e-9, "stage-probe component activation lift-ratio deviation too large")
        v.check(0.0 <= source_fraction <= 1.0 + 1.0e-12, "stage-probe component activation source fraction out of range")
        v.check(0.0 <= lifted_fraction <= 1.0 + 1.0e-12, "stage-probe component activation lifted fraction out of range")
        v.check(as_float(row, "max_component_activation_residual_norm") < 1.0e-9, "stage-probe component activation residual too large")
        v.check(as_float(row, "max_component_activation_stage_residual_norm") < 1.0e-9, "stage-probe component activation stage residual too large")
        v.check(as_float(row, "max_endpoint_position_constraint_norm") < 1.0e-10, "stage-probe component activation position constraint too large")
        v.check(as_float(row, "max_endpoint_velocity_constraint_norm") < 1.0e-10, "stage-probe component activation velocity constraint too large")
        v.check(math.isfinite(as_float(row, "component_source_observed_order")), "stage-probe component activation source order is not finite")
        v.check(math.isfinite(as_float(row, "component_lifted_probe_observed_order")), "stage-probe component activation lifted order is not finite")
        probe_norm = as_float(row, "max_activated_probe_component_norm")
        v.check(math.isfinite(probe_norm) and probe_norm >= 0.0, "stage-probe component activation probe norm is not finite")
        positive_probe = positive_probe or probe_norm > 0.0
    v.check(positive_probe, "stage-probe component activation probe is identically zero")
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"stage-probe component activation cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        hs = sorted(as_float(row, "h") for row in case_rows)
        v.check(hs == [0.01, 0.02, 0.04], f"stage-probe component activation h sweep mismatch for {case}: {hs}")
        v.check({row["component"] for row in case_rows} == {target_component}, f"stage-probe component activation components mismatch for {case}")
        split_components = {row["component"] for row in split_by_case.get(case, [])}
        dominant_split_rows = [
            row for row in split_by_case.get(case, [])
            if row["component"] == target_component
            and as_float(row, "component_source_fraction_of_block") > 0.9
        ]
        v.check(target_component in split_components, f"stage-probe component activation missing source-split target for {case}")
        v.check(bool(dominant_split_rows), f"stage-probe component activation target is not dominant in source split for {case}")


