    positive_probe = False
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        h = as_float(row, "h")
        formula_source = as_float(row, "formula_source_norm")
        formula_lifted = as_float(row, "formula_lifted_probe_norm")
        generic_lifted = as_float(row, "generic_component_lifted_probe_norm")
        formula_diff = as_float(row, "formula_vs_generic_component_probe_norm")
        expected_lifted = as_float(row, "expected_formula_lifted_probe_norm")
        ratio = as_float(row, "formula_lift_norm_ratio")
        ratio_deviation = as_float(row, "formula_lift_norm_ratio_deviation")
        source_fraction = as_float(row, "formula_source_fraction_of_block")
        activation_residual = as_float(row, "activation_residual_norm")
        activation_probe = as_float(row, "activation_probe_norm")
        derived_probe = as_float(row, "max_derived_formula_component_probe_norm")

        v.check(row["status"] == "stage_probe_component_formula_solved_not_full_tfe", "stage-probe component formula status changed")
        v.check(row["component"] == target_component, "stage-probe component formula target changed")
        v.check(row["block"] == "newton_euler_weak_balance", "stage-probe component formula block changed")
