        ratio_deviation = as_float(row, "formula_lift_norm_ratio_deviation")
        block_diff = as_float(row, "max_block_formula_vs_generic_probe_norm")
        residual = as_float(row, "max_all_source_formula_residual_norm")
        stage_residual = as_float(row, "max_all_source_formula_stage_residual_norm")
