        v.check(row["source_is_endpoint_boundary_only"] == "True", "stage-probe all-source formula lost endpoint-boundary marker")
        v.check(row["stage_equations_are_tfe_weighted"] == "True", "stage-probe all-source formula should use weighted stage rows")
        v.check(row["non_equivalent_to_gauss6"] == "True", "stage-probe all-source formula should be non-equivalent")
        v.check(row["solved_as_residual"] == "True", "stage-probe all-source formula is not marked solved")
        v.check(row["full_tfe_stage_replacement"] == "False", "stage-probe all-source formula overclaims full TFE replacement")
