        v.check(math.isclose(formula_lifted, expected_lifted, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe all-source formula lifted norm mismatch")
        v.check(math.isclose(generic_lifted, formula_lifted, rel_tol=1.0e-9, abs_tol=1.0e-18), "stage-probe all-source formula generic lifted norm mismatch")
        v.check(formula_diff < 1.0e-12, "stage-probe all-source formula differs from generic stage-major probe")
        v.check(block_diff < 1.0e-12, "stage-probe all-source formula block lift differs from generic blocks")
        v.check(math.isclose(ratio, 1.0, rel_tol=1.0e-9, abs_tol=1.0e-9), "stage-probe all-source formula lift ratio not one")
        v.check(ratio_deviation < 1.0e-9, "stage-probe all-source formula lift-ratio deviation too large")
        v.check(residual < 1.0e-9, "stage-probe all-source formula residual too large")
        v.check(stage_residual < 1.0e-9, "stage-probe all-source formula stage residual too large")
        v.check(as_float(row, "max_endpoint_position_constraint_norm") < 1.0e-10, "stage-probe all-source formula position constraint too large")
        v.check(as_float(row, "max_endpoint_velocity_constraint_norm") < 1.0e-10, "stage-probe all-source formula velocity constraint too large")
