def validate_endpoint_tfe_full_stage_acceptance_gap(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_full_stage_acceptance_gap_audit.csv")
    bridge_rows = v.read_csv("cylindrical_chain_endpoint_tfe_stage_probe_all_source_trajectory_bridge_audit.csv")
    bridge_by_key = {
        (row["case"], as_float(row, "h")): row
        for row in bridge_rows
    }
    by_case: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        h = as_float(row, "h")
        proxy_residual = as_float(row, "proxy_residual_norm")
        proxy_stage_residual = as_float(row, "proxy_stage_residual_norm")
        proxy_probe = as_float(row, "proxy_formula_probe_norm")
        position_error = as_float(row, "position_error_vs_proxy_reference")
        velocity_error = as_float(row, "velocity_error_vs_proxy_reference")

        v.check(row["status"] == "full_stage_acceptance_gap_quantified_not_full_tfe", "full-stage acceptance gap status changed")
        v.check(row["all_source_trajectory_bridge_status"] == "stage_probe_all_source_trajectory_bridge_solved_not_full_tfe", "full-stage acceptance gap bridge status changed")
        v.check(row["reference_h"] == "0.005", "full-stage acceptance gap reference h changed")
        v.check(row["four_asme_gate_status"] == "four_asme_method_rows_accepted_projection_sharp_sparse_caveats", "full-stage acceptance gap ASME status changed")
        v.check(row["four_asme_gate_compatible"] == "True", "full-stage acceptance gap lost ASME compatibility")
        v.check(row["h_sweep_present"] == "True", "full-stage acceptance gap lost h-sweep evidence")
        v.check(row["math_proof_status"] == "conditional_not_full_tfe", "full-stage acceptance gap math proof status changed")
        v.check(int(row["stage_row_budget"]) == 132, "full-stage acceptance gap stage row budget changed")
        v.check(int(row["endpoint_square_extension_rows"]) == 40, "full-stage acceptance gap endpoint extension row count changed")
        v.check(int(row["readiness_satisfied"]) >= 28, "full-stage acceptance gap readiness satisfied count regressed")
        v.check(int(row["readiness_missing"]) >= 1, "full-stage acceptance gap lost readiness missing caveat")
        v.check(int(row["design_partial"]) >= 19, "full-stage acceptance gap design partial count regressed")
        v.check(int(row["design_missing"]) >= 2, "full-stage acceptance gap design missing count regressed")
        v.check(row["proxy_residual_solved"] == "True", "full-stage acceptance gap proxy residual not solved")
        v.check(row["endpoint_boundary_source_removed"] == "False", "full-stage acceptance gap overclaims endpoint-boundary source removal")
        v.check(row["derived_full_tfe_stage_functional_present"] == "False", "full-stage acceptance gap overclaims derived full-TFE functional")
        v.check(row["full_tfe_stage_replacement"] == "False", "full-stage acceptance gap overclaims full TFE replacement")
        v.check(int(row["acceptance_satisfied_count"]) >= 5, "full-stage acceptance gap satisfied checks regressed")
        v.check(int(row["acceptance_missing_count"]) >= 3, "full-stage acceptance gap missing checks no longer record blockers")
        v.check("full-TFE" in row["blocking_gap"] and "stage" in row["blocking_gap"], "full-stage acceptance gap blocking text missing full-TFE stage gap")
        v.check(math.isfinite(proxy_probe) and proxy_probe >= 0.0, "full-stage acceptance gap proxy probe invalid")
        v.check(math.isfinite(position_error) and position_error >= 0.0, "full-stage acceptance gap position error invalid")
        v.check(math.isfinite(velocity_error) and velocity_error >= 0.0, "full-stage acceptance gap velocity error invalid")
        v.check(proxy_residual < 1.0e-9, "full-stage acceptance gap proxy residual too large")
        v.check(proxy_stage_residual < 1.0e-9, "full-stage acceptance gap proxy stage residual too large")

        bridge_row = bridge_by_key.get((row["case"], h), {})
        v.check(bool(bridge_row), f"full-stage acceptance gap missing bridge link for {row['case']} h={h}")
        if bridge_row:
            v.check(math.isclose(proxy_residual, as_float(bridge_row, "max_all_source_trajectory_residual_norm"), rel_tol=1.0e-12, abs_tol=1.0e-18), "full-stage acceptance gap proxy residual no longer matches bridge")
            v.check(math.isclose(proxy_stage_residual, as_float(bridge_row, "max_all_source_trajectory_stage_residual_norm"), rel_tol=1.0e-12, abs_tol=1.0e-18), "full-stage acceptance gap proxy stage residual no longer matches bridge")
            v.check(math.isclose(proxy_probe, as_float(bridge_row, "max_all_source_formula_probe_norm"), rel_tol=1.0e-12, abs_tol=1.0e-18), "full-stage acceptance gap proxy probe no longer matches bridge")

    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"full-stage acceptance gap cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        hs = sorted(as_float(row, "h") for row in case_rows)
        v.check(hs == [0.01, 0.02, 0.04], f"full-stage acceptance gap h sweep mismatch for {case}: {hs}")


