def validate_endpoint_tfe_paper_formula_mapping(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_paper_formula_mapping_audit.csv")
    hs = sorted(as_float(row, "h") for row in rows)
    v.check(hs == [0.01, 0.02, 0.04], f"paper TFE formula mapping h sweep mismatch: {hs}")
    alpha_norms = []
    beta_norms = []
    gamma_norms = []
    for row in rows:
        v.check(row["status"] == "paper_tfe_coefficients_encoded_residual_not_replaced", "paper TFE formula mapping status changed")
        v.check("Eq-43" in row["paper_source"], "paper TFE formula mapping does not cite Eq-43")
        v.check(row["node_family"] == "Gauss-Lobatto", "paper TFE formula mapping node family changed")
        v.check(row["paper_requires_nodal_xyz"] == "True", "paper TFE formula mapping lost nodal xyz requirement")
        v.check(row["v047_uses_gauss_stage_collocation"] == "True", "paper TFE formula mapping lost v047 stage-collocation marker")
        v.check(row["paper_coefficients_encoded"] == "True", "paper TFE coefficients are not marked encoded")
        v.check(row["residual_replacement_ready"] == "False", "paper TFE formula mapping overclaims residual replacement readiness")
        v.check(row["full_tfe_stage_replacement"] == "False", "paper TFE formula mapping overclaims full TFE replacement")
        v.check(int(row["method_degree"]) == 3, "paper TFE formula mapping method degree changed")
        v.check(int(row["expected_order"]) == 5, "paper TFE formula mapping expected order changed")
        v.check(int(row["paper_unknown_nodes"]) == 3, "paper TFE formula mapping unknown-node count changed")
        v.check(int(row["v047_stage_nodes"]) == 3, "paper TFE formula mapping v047 stage-node count changed")
        v.check(int(row["paper_augmented_dim_6n_plus_c"]) == 20, "paper TFE formula mapping augmented dimension changed")
        v.check(int(row["v047_stage_size"]) == 44, "paper TFE formula mapping v047 stage size changed")
        alpha_norms.append(as_float(row, "paper_alpha_h_fro_norm"))
        beta_norms.append(as_float(row, "paper_beta_h_l2_norm"))
        gamma_norms.append(as_float(row, "paper_gamma_l2_norm"))
        v.check(as_float(row, "paper_alpha_h_condition") > 1.0, "paper TFE alpha condition should be finite and nontrivial")
        v.check("nodal TFE" in row["blocking_gap"], "paper TFE formula mapping blocking gap is incomplete")
    v.check(max(alpha_norms) - min(alpha_norms) < 1.0e-12, "paper TFE alpha*h norm should be h-invariant")
    v.check(max(beta_norms) - min(beta_norms) < 1.0e-12, "paper TFE beta*h norm should be h-invariant")
    v.check(max(gamma_norms) - min(gamma_norms) < 1.0e-12, "paper TFE gamma norm should be h-invariant")


