        v.check(int(row["paper_x_unknown_dim"]) == 60, "paper TFE derivative operator x unknown dimension changed")
        v.check(int(row["paper_yz_derived_dim"]) == 120, "paper TFE derivative operator y/z dimension changed")
        v.check(int(row["paper_total_xyz_dim"]) == 180, "paper TFE derivative operator total xyz dimension changed")
        v.check(int(row["v047_stage_unknown_dim"]) == 132, "paper TFE derivative operator v047 stage dimension changed")
        v.check(int(row["v047_stage_size"]) == 44, "paper TFE derivative operator v047 stage size changed")
        v.check(int(row["v047_position_like_dim_per_stage"]) == 12, "paper TFE derivative operator position-like dim changed")
        v.check(int(row["v047_velocity_like_dim_per_stage"]) == 12, "paper TFE derivative operator velocity-like dim changed")
        v.check(int(row["v047_acceleration_like_dim_per_stage"]) == 12, "paper TFE derivative operator acceleration-like dim changed")
        v.check(int(row["v047_multiplier_dim_per_stage"]) == 8, "paper TFE derivative operator multiplier dim changed")
