        v.check(as_float(row, "quadratic_z_reproduction_error") < 1.0e-8, "paper TFE derivative operator z reproduction error too large")
        v.check(as_float(row, "max_relation_residual_norm") < 1.0e-14, "paper TFE derivative operator relation residual too large")
        v.check(row["operator_ready_for_residual_assembly"] == "True", "paper TFE derivative operator lost assembly-ready marker")
        v.check(row["v047_uses_gauss_stage_collocation"] == "True", "paper TFE derivative operator lost current Gauss-stage marker")
        v.check(row["residual_replacement_ready"] == "False", "paper TFE derivative operator overclaims residual replacement readiness")
        v.check(row["full_tfe_stage_replacement"] == "False", "paper TFE derivative operator overclaims full TFE replacement")
