def validate_endpoint_tfe_paper_position_substitution_candidate(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_paper_position_substitution_candidate_audit.csv")
    by_case: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        v.check(row["status"] == "paper_tfe_position_rows_substituted_order_limited_not_full_tfe", f"paper TFE position-substitution status changed for {row['case']} h={row['h']}")
        v.check(int(row["row_families_substituted"]) == 2, "paper TFE position-substitution family count changed")
        v.check(int(row["stage_rows_substituted"]) == 36, "paper TFE position-substitution stage-row count changed")
        v.check(row["residual_substituted"] == "True", "paper TFE position-substitution no longer records residual substitution")
        v.check(row["accepted_h_sweep_present"] == "False", "paper TFE position-substitution overclaims accepted h-sweep")
        v.check(row["full_tfe_stage_replacement"] == "False", "paper TFE position-substitution overclaims full replacement")
        v.check(as_float(row, "max_paper_position_substitution_residual_norm") < 1e-9, "paper TFE position-substitution residual too large")
        v.check(as_float(row, "max_paper_position_row_norm") < 1e-9, "paper TFE position-row residual too large")
        v.check(math.isfinite(as_float(row, "max_endpoint_constraint_norm")) and as_float(row, "max_endpoint_constraint_norm") < 1e-3, "paper TFE position-substitution endpoint constraint diagnostic invalid")
        v.check(as_float(row, "max_endpoint_velocity_constraint_norm") < 1e-9, "paper TFE position-substitution endpoint velocity constraint too large")
        v.check(int(row["min_jacobian_rank"]) == 132, "paper TFE position-substitution Jacobian is not full rank")
        v.check(math.isfinite(as_float(row, "max_jacobian_condition")) and as_float(row, "max_jacobian_condition") > 0.0, "paper TFE position-substitution condition number invalid")
        v.check("order-limited" in row["blocking_gap"], "paper TFE position-substitution does not keep order-limited caveat")
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"paper TFE position-substitution cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        hs = sorted(as_float(row, "h") for row in case_rows)
        v.check(hs == [0.01, 0.02, 0.04], f"paper TFE position-substitution h sweep mismatch for {case}: {hs}")
        orders = {
            (
                round(as_float(row, "position_observed_order"), 12),
                round(as_float(row, "velocity_observed_order"), 12),
            )
            for row in case_rows
        }
        v.check(len(orders) == 1, f"paper TFE position-substitution orders inconsistent for {case}: {orders}")
        order = next(iter(orders))
        v.check(math.isfinite(order[0]) and math.isfinite(order[1]), f"paper TFE position-substitution orders not finite for {case}: {order}")
        v.check(min(order) < 5.5, f"paper TFE position-substitution no longer documents order-limited candidate for {case}: {order}")


