def validate_endpoint_tfe_paper_all_row_consistent_z0_conditioning(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_paper_all_row_consistent_z0_conditioning_audit.csv")
    by_case: dict[str, list[dict[str, str]]] = {}
    expected_left = {
        "translational_position_weak_defect",
        "rotational_lie_position_weak_defect",
        "translational_velocity_weak_defect",
        "angular_velocity_weak_defect",
        "newton_euler_weak_balance",
        "lower_pair_index3_weak_constraints",
    }
    expected_right = {
        "lie_position_u",
        "translation_position_r",
        "translation_velocity_v",
        "angular_velocity_w",
        "translation_acceleration_a",
        "angular_acceleration_alpha",
        "lower_pair_lambda",
    }
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        v.check(
            row["status"] == "paper_tfe_all_row_consistent_z0_conditioning_quantified_not_accepted",
            f"paper TFE consistent-z0 conditioning status changed for {row['case']} h={row['h']}",
        )
        v.check(as_float(row, "residual_norm") < 1e-9, "paper TFE consistent-z0 conditioning residual too large")
        v.check(as_float(row, "linear_residual_norm") < 1e-9, "paper TFE consistent-z0 conditioning linear residual too large")
        v.check(int(row["min_jacobian_rank"]) == 132, "paper TFE consistent-z0 conditioning Jacobian is not full rank")
        v.check(as_float(row, "raw_condition") > 1.0e10, "paper TFE consistent-z0 conditioning no longer records severe raw condition")
        v.check(math.isfinite(as_float(row, "row_scaled_condition")), "paper TFE consistent-z0 row-scaled condition not finite")
        v.check(math.isfinite(as_float(row, "column_scaled_condition")), "paper TFE consistent-z0 column-scaled condition not finite")
        v.check(math.isfinite(as_float(row, "row_column_scaled_condition")), "paper TFE consistent-z0 row-column-scaled condition not finite")
        v.check(math.isfinite(as_float(row, "iterative_equilibrated_condition")), "paper TFE consistent-z0 iterative condition not finite")
        v.check(as_float(row, "condition_reduction_raw_to_iterative") > 1.0e6, "paper TFE consistent-z0 iterative scaling no longer explains large conditioning component")
        v.check(as_float(row, "min_singular_value") > 0.0, "paper TFE consistent-z0 min singular value not positive")
        v.check(as_float(row, "max_singular_value") > as_float(row, "min_singular_value"), "paper TFE consistent-z0 singular values invalid")
        v.check(row["dominant_left_row_family"] in expected_left, "paper TFE consistent-z0 dominant row family invalid")
        v.check(row["dominant_right_variable_family"] in expected_right, "paper TFE consistent-z0 dominant variable family invalid")
        v.check(0.0 <= as_float(row, "dominant_left_row_family_fraction") <= 1.0, "paper TFE consistent-z0 dominant row fraction invalid")
        v.check(0.0 <= as_float(row, "dominant_right_variable_family_fraction") <= 1.0, "paper TFE consistent-z0 dominant variable fraction invalid")
        left_sum = sum(as_float(row, f"left_fraction_{name}") for name in expected_left)
        right_sum = sum(as_float(row, f"right_fraction_{name}") for name in expected_right)
        v.check(math.isclose(left_sum, 1.0, rel_tol=1e-8, abs_tol=1e-8), f"paper TFE consistent-z0 left fractions do not sum to 1: {left_sum}")
        v.check(math.isclose(right_sum, 1.0, rel_tol=1e-8, abs_tol=1e-8), f"paper TFE consistent-z0 right fractions do not sum to 1: {right_sum}")
        v.check(int(row["row_families_substituted"]) == 6, "paper TFE consistent-z0 conditioning family count changed")
        v.check(int(row["stage_rows_substituted"]) == 132, "paper TFE consistent-z0 conditioning stage rows changed")
        v.check(int(row["bootstrap_step_count"]) == 0, "paper TFE consistent-z0 conditioning should not use bootstrap")
        v.check(as_float(row, "initial_z0_residual_norm") < 1e-10, "paper TFE consistent-z0 conditioning initial z0 residual too large")
        v.check(int(row["initial_z0_jacobian_rank"]) == 20, "paper TFE consistent-z0 conditioning initial z0 rank changed")
        v.check(as_float(row, "initial_z0_jacobian_condition") < 100.0, "paper TFE consistent-z0 conditioning initial z0 condition changed")
        v.check(row["accepted_h_sweep_present"] == "False", "paper TFE consistent-z0 conditioning overclaims accepted h-sweep")
        v.check(row["full_tfe_stage_replacement"] == "False", "paper TFE consistent-z0 conditioning overclaims full replacement")
        v.check("conditioning" in row["blocking_gap"], "paper TFE consistent-z0 conditioning caveat missing")
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"paper TFE consistent-z0 conditioning cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        hs = sorted(as_float(row, "h") for row in case_rows)
        v.check(hs == [0.01, 0.02, 0.04], f"paper TFE consistent-z0 conditioning h sweep mismatch for {case}: {hs}")


