        by_case.setdefault(row["case"], []).append(row)
        v.check(
            row["status"] == "paper_tfe_lower_pair_acceleration_terminal_output_h_sweep_diagnostic_not_accepted",
            f"paper TFE lower-pair acceleration terminal-output status changed for {row['case']} h={row['h']}",
        )
        v.check(as_float(row, "max_paper_lower_pair_acceleration_terminal_residual_norm") < 1e-9, "paper TFE lower-pair acceleration terminal residual too large")
        v.check(as_float(row, "max_paper_kinematic_row_norm") < 1e-8, "paper TFE lower-pair acceleration kinematic rows too large")
        v.check(as_float(row, "max_paper_newton_euler_row_norm") < 1e-8, "paper TFE lower-pair acceleration Newton-Euler rows too large")
