        v.check(math.isfinite(as_float(row, "position_observed_order")), "paper TFE terminal-velocity closure position order not finite")
        v.check(math.isfinite(as_float(row, "velocity_observed_order")), "paper TFE terminal-velocity closure velocity order not finite")
