        v.check(row["output_policy"] == "raw_terminal_paper_lobatto_node_no_endpoint_projection", "paper TFE terminal-velocity closure output policy changed")
        v.check(int(row["paper_stage_rows_retained"]) == 124, "paper TFE terminal-velocity closure retained paper-row count changed")
        v.check(int(row["endpoint_velocity_rows_inserted"]) == 8, "paper TFE terminal-velocity closure inserted endpoint row count changed")
