def validate_endpoint_tfe_paper_lower_pair_acceleration_terminal_row_homotopy(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_paper_lower_pair_acceleration_terminal_row_homotopy_audit.csv")
    expected_cases = {"cylindrical_smooth", "cylindrical_sharp"}
    expected_h = [0.01, 0.02, 0.04]
    expected_beta = [0.0, 0.25, 0.5, 0.75, 1.0]
    by_case_h: dict[tuple[str, float], list[dict[str, str]]] = {}
    beta0_velocity = []
    beta1_velocity = []
    beta1_rows = 0
    for row in rows:
        h = as_float(row, "h")
        beta = as_float(row, "beta")
        by_case_h.setdefault((row["case"], h), []).append(row)
        v.check(
            row["status"] == "paper_tfe_lower_pair_acceleration_terminal_row_homotopy_diagnostic_not_accepted",
            f"paper TFE terminal-row homotopy status changed for {row['case']} h={row['h']} beta={row['beta']}",
        )
        v.check(row["case"] in expected_cases, f"paper TFE terminal-row homotopy unexpected case {row['case']}")
        v.check(h in expected_h, f"paper TFE terminal-row homotopy unexpected h={h}")
        v.check(beta in expected_beta, f"paper TFE terminal-row homotopy unexpected beta={beta}")
        v.check(as_float(row, "residual_norm") < 1e-9, "paper TFE terminal-row homotopy residual too large")
        v.check(as_float(row, "terminal_endpoint_constraint_norm") < 1e-6, "paper TFE terminal-row homotopy endpoint position constraint too large")
        for key in [
            "terminal_endpoint_velocity_constraint_norm",
            "terminal_lower_pair_acceleration_row_norm",
            "terminal_velocity_row_norm",
            "homotopy_terminal_row_norm",
            "retained_row_norm",
            "removed_gauss_residual_norm",
        ]:
            value = as_float(row, key)
            v.check(math.isfinite(value), f"paper TFE terminal-row homotopy {key} is not finite")
            v.check(value >= 0.0, f"paper TFE terminal-row homotopy {key} is negative")
        if abs(beta) < 1.0e-15:
            beta0_velocity.append(as_float(row, "terminal_endpoint_velocity_constraint_norm"))
        if abs(beta - 1.0) < 1.0e-15:
            beta1_rows += 1
            beta1_velocity.append(as_float(row, "terminal_endpoint_velocity_constraint_norm"))
            v.check(as_float(row, "terminal_endpoint_velocity_constraint_norm") < 1e-10, "paper TFE terminal-row homotopy beta=1 endpoint velocity too large")
        v.check(int(row["min_jacobian_rank"]) == 132, "paper TFE terminal-row homotopy Jacobian is not full rank")
        v.check(math.isfinite(as_float(row, "raw_jacobian_condition")), "paper TFE terminal-row homotopy raw condition not finite")
        v.check(math.isfinite(as_float(row, "scaled_jacobian_condition")), "paper TFE terminal-row homotopy scaled condition not finite")
        v.check(as_float(row, "raw_jacobian_condition") > as_float(row, "scaled_jacobian_condition"), "paper TFE terminal-row homotopy scaling does not reduce condition")
        v.check(as_float(row, "condition_reduction_raw_to_scaled") > 1.0, "paper TFE terminal-row homotopy condition reduction missing")
        v.check(as_float(row, "raw_linear_residual_norm") < 1e-7, "paper TFE terminal-row homotopy raw linear residual too large")
        v.check(as_float(row, "scaled_linear_residual_norm") < 1e-7, "paper TFE terminal-row homotopy scaled linear residual too large")
        v.check(as_float(row, "initial_z0_residual_norm") < 1e-10, "paper TFE terminal-row homotopy initial z0 residual too large")
        v.check(int(row["initial_z0_jacobian_rank"]) == 20, "paper TFE terminal-row homotopy initial z0 rank changed")
        v.check(as_float(row, "initial_z0_jacobian_condition") < 100.0, "paper TFE terminal-row homotopy initial z0 condition changed")
        v.check(row["linear_solve_policy"] == "iterative_equilibrated", "paper TFE terminal-row homotopy linear solve policy changed")
        v.check(row["output_policy"] == "raw_terminal_paper_lobatto_node_no_endpoint_projection", "paper TFE terminal-row homotopy output policy changed")
        v.check(row["start_z0_policy"] == "consistent_initial_acceleration_one_step", "paper TFE terminal-row homotopy start-z0 policy changed")
        v.check(row["homotopy_policy"] == "terminal_rows_equal_(1-beta)*lower_pair_acceleration_plus_beta*endpoint_velocity", "paper TFE terminal-row homotopy policy changed")
        v.check(row["accepted_h_sweep_present"] == "False", "paper TFE terminal-row homotopy overclaims accepted h-sweep")
        v.check(row["full_tfe_stage_replacement"] == "False", "paper TFE terminal-row homotopy overclaims full replacement")
    v.check({case for case, _ in by_case_h} == expected_cases, f"paper TFE terminal-row homotopy cases mismatch: {sorted({case for case, _ in by_case_h})}")
    for case in expected_cases:
        hs = sorted({h for case_name, h in by_case_h if case_name == case})
        v.check(hs == expected_h, f"paper TFE terminal-row homotopy h sweep mismatch for {case}: {hs}")
        for h in expected_h:
            betas = sorted(as_float(row, "beta") for row in by_case_h.get((case, h), []))
            v.check(betas == expected_beta, f"paper TFE terminal-row homotopy beta path mismatch for {case} h={h}: {betas}")
    v.check(beta1_rows == 6, "paper TFE terminal-row homotopy beta=1 row count changed")
    v.check(max(beta0_velocity, default=0.0) > max(beta1_velocity, default=1.0), "paper TFE terminal-row homotopy lost beta0/beta1 velocity contrast")


