        v.check(int(row["source_insertion_residual_clean_step_count"]) == int(row["steps"]), "paper TFE direct endpoint source residual-clean steps regressed")
        v.check(row["source_policy"] == "direct_acceleration_predictor_raw_endpoint_velocity_source", "paper TFE direct endpoint source policy changed")
        v.check(row["terminal_velocity_closure_used"] == "False", "paper TFE direct endpoint source used terminal closure")
        v.check(row["terminal_row_replacement_source_used"] == "False", "paper TFE direct endpoint source used terminal-row replacement as source")
