        v.check(int(row["source_residual_substituted_step_count"]) == int(row["steps"]), "paper TFE direct source residual-substitution step count regressed")
        v.check(int(row["source_insertion_residual_clean_step_count"]) == int(row["steps"]), "paper TFE direct source residual-substitution residual-clean steps regressed")
        v.check(row["source_policy"] == "direct_acceleration_predictor_raw_endpoint_velocity_source", "paper TFE direct source residual-substitution policy changed")
        v.check(row["row_family"] == "lower_pair_index3_weak_constraints", "paper TFE direct source residual-substitution row family changed")
