        v.check(row["accepted_h_sweep_present"] == "False", "paper TFE direct source residual-substitution overclaims accepted h-sweep")
        v.check(row["full_tfe_stage_replacement"] == "False", "paper TFE direct source residual-substitution overclaims full replacement")
