        v.check(row["source_policy"] == "endpoint_velocity_source_computed_inside_newton_residual_from_current_terminal_paper_node", "paper TFE self-consistent endpoint-source policy changed")
        v.check(row["row_family"] == "lower_pair_index3_weak_constraints", "paper TFE self-consistent endpoint-source row family changed")
