def validate_endpoint_tfe_paper_lower_pair_source_free_order_closure_blend_trajectory(v: Validator) -> None:
    rows = v.read_csv(
        "cylindrical_chain_endpoint_tfe_paper_lower_pair_source_free_order_closure_blend_trajectory_audit.csv"
    )
    expected_cases = {"cylindrical_smooth", "cylindrical_sharp"}
    expected_betas = {0.0, 0.5, 1.0}
    expected_status = "paper_tfe_lower_pair_source_free_order_closure_blend_trajectory_tradeoff_not_full_tfe"
    by_case_beta: dict[tuple[str, float], list[dict[str, str]]] = {}
    max_residual = 0.0
    max_terminal_velocity = 0.0
    max_order_closure_row = 0.0
    max_position_order = 0.0
    max_velocity_order = 0.0
    beta1_terminal = 0.0
    beta0_terminal = 0.0
    beta0_smooth_position_order = 0.0
    beta1_smooth_position_order = 0.0
    for row in rows:
        beta = as_float(row, "beta")
        case = row["case"]
        by_case_beta.setdefault((case, beta), []).append(row)
        v.check(row["status"] == expected_status, f"paper TFE order/closure blend status changed for {case} beta={beta} h={row['h']}")
        v.check(row["reference_completed"] == "True", "paper TFE order/closure blend reference did not complete")
        v.check(row["trajectory_completed"] == "True", "paper TFE order/closure blend trajectory did not complete")
        v.check(int(row["row_families_substituted"]) == 6, "paper TFE order/closure blend row-family count changed")
        v.check(int(row["stage_rows_substituted"]) == 132, "paper TFE order/closure blend stage-row count changed")
        v.check(int(row["source_consistency_rows"]) == 16, "paper TFE order/closure blend source-consistency rows changed")
        v.check(int(row["order_closure_blend_closure_rows"]) == 8, "paper TFE order/closure blend closure rows changed")
        v.check(int(row["source_free_lower_pair_rows"]) == 24, "paper TFE order/closure blend lower-pair row count changed")
        v.check(row["lower_pair_row_formula"] == "centered_acceleration_source_consistency_plus_order_closure_blend", "paper TFE order/closure blend formula changed")
        v.check(row["order_preserving_baseline_formula"] == "mean_acceleration_closure", "paper TFE order/closure blend order baseline changed")
        v.check(row["terminal_closure_baseline_formula"] == "final_stage_velocity_closure", "paper TFE order/closure blend terminal baseline changed")
        v.check(row["linear_solve_policy"] == "iterative_equilibrated", "paper TFE order/closure blend linear solve policy changed")
        v.check(row["output_policy"] == "raw_terminal_lobatto_node_no_projection", "paper TFE order/closure blend output policy changed")
        v.check(row["start_z0_policy"] == "consistent_initial_acceleration_then_recurrent_terminal_z", "paper TFE order/closure blend z0 policy changed")
        v.check(row["external_endpoint_source_removed"] == "True", "paper TFE order/closure blend did not remove external endpoint source")
        v.check(row["endpoint_boundary_source_removed"] == "True", "paper TFE order/closure blend did not remove endpoint-boundary source")
        v.check(row["terminal_row_replacement_used"] == "False", "paper TFE order/closure blend unexpectedly uses terminal-row replacement")
        v.check(row["projection_used"] == "False", "paper TFE order/closure blend unexpectedly uses projection")
        v.check(row["trajectory_h_sweep_present"] == "True", "paper TFE order/closure blend did not record h-sweep")
        v.check(row["accepted_h_sweep_present"] == "False", "paper TFE order/closure blend overclaims accepted h-sweep")
        v.check(row["full_tfe_stage_replacement"] == "False", "paper TFE order/closure blend overclaims full replacement")
        v.check(row["order_closure_tradeoff_present"] == "True", "paper TFE order/closure blend tradeoff marker changed")
        v.check(row["order_and_terminal_intersection_present"] == "False", "paper TFE order/closure blend unexpectedly found a full intersection")
        v.check(int(row["beta_count"]) == 3, "paper TFE order/closure blend beta count changed")
        v.check({float(value) for value in row["beta_values"].split(",")} == expected_betas, "paper TFE order/closure blend beta path changed")
        residual = as_float(row, "max_residual_norm")
        terminal_velocity = as_float(row, "max_raw_terminal_endpoint_velocity_constraint_norm")
        order_closure_row = as_float(row, "max_order_closure_blend_closure_row_norm")
        pos_order = as_float(row, "position_observed_order")
        vel_order = as_float(row, "velocity_observed_order")
        pos_err = as_float(row, "position_error_vs_source_free_order_closure_blend_reference")
        vel_err = as_float(row, "velocity_error_vs_source_free_order_closure_blend_reference")
        v.check(residual < 1.0e-8, "paper TFE order/closure blend residual too large")
        v.check(order_closure_row < 1.0e-8, "paper TFE order/closure blend closure row too large")
        v.check(int(row["min_jacobian_rank"]) == 132, "paper TFE order/closure blend lost full rank")
        v.check(int(row["initial_z0_jacobian_rank"]) == 20, "paper TFE order/closure blend initial z0 rank changed")
        v.check(math.isfinite(as_float(row, "max_scaled_jacobian_condition")), "paper TFE order/closure blend scaled condition not finite")
        v.check(pos_err > 0.0 and vel_err > 0.0, "paper TFE order/closure blend errors are identically zero")
        max_residual = max(max_residual, residual)
        max_terminal_velocity = max(max_terminal_velocity, terminal_velocity)
        max_order_closure_row = max(max_order_closure_row, order_closure_row)
        max_position_order = max(max_position_order, pos_order)
        max_velocity_order = max(max_velocity_order, vel_order)
        if abs(beta) < 1.0e-12:
            beta0_terminal = max(beta0_terminal, terminal_velocity)
            if case == "cylindrical_smooth":
                beta0_smooth_position_order = max(beta0_smooth_position_order, pos_order)
        if abs(beta - 1.0) < 1.0e-12:
            beta1_terminal = max(beta1_terminal, terminal_velocity)
            if case == "cylindrical_smooth":
                beta1_smooth_position_order = max(beta1_smooth_position_order, pos_order)
    v.check(len(rows) == 18, "paper TFE order/closure blend should have eighteen case/beta/h rows")
    v.check({case for case, _beta in by_case_beta} == expected_cases, "paper TFE order/closure blend cases changed")
    v.check({beta for _case, beta in by_case_beta} == expected_betas, "paper TFE order/closure blend beta values changed")
    for (case, beta), case_rows in by_case_beta.items():
        hs = sorted(as_float(row, "h") for row in case_rows)
        v.check(hs == [0.01, 0.02, 0.04], f"paper TFE order/closure blend h sweep mismatch for {case} beta={beta}: {hs}")
    v.check(max_residual < 1.0e-8, "paper TFE order/closure blend max residual too large")
    v.check(max_order_closure_row < 1.0e-8, "paper TFE order/closure blend max closure row too large")
    v.check(beta0_terminal > 1.0e-6, "paper TFE order/closure beta=0 no longer exposes terminal-velocity blocker")
    v.check(beta1_terminal < 1.0e-10, "paper TFE order/closure beta=1 no longer closes terminal velocity")
    v.check(max_terminal_velocity > 1.0e-6, "paper TFE order/closure sweep no longer records the tradeoff terminal blocker")
    v.check(beta0_smooth_position_order > 5.0, "paper TFE order/closure beta=0 smooth order regressed")
    v.check(3.0 < beta1_smooth_position_order < 4.5, "paper TFE order/closure beta=1 smooth order range changed")
    v.check(max_position_order > 5.0, "paper TFE order/closure blend lost high-order endpoint of tradeoff")
    v.check(max_velocity_order > 6.0, "paper TFE order/closure blend velocity order regressed")


