        v.check(row["terminal_row_replacement_used"] == "False", "paper TFE component-blend trajectory unexpectedly uses terminal-row replacement")
        v.check(row["projection_used"] == "False", "paper TFE component-blend trajectory unexpectedly uses projection")
        v.check(row["trajectory_h_sweep_present"] == "True", "paper TFE component-blend trajectory lost trajectory marker")
        v.check(row["one_step_h_sweep_present"] == "False", "paper TFE component-blend trajectory overclaims one-step sweep marker")
        v.check(row["accepted_h_sweep_present"] == "False", "paper TFE component-blend trajectory overclaims accepted h-sweep")
        v.check(row["full_tfe_stage_replacement"] == "False", "paper TFE component-blend trajectory overclaims full replacement")
        v.check(row["componentwise_blend_present"] == "True", "paper TFE component-blend trajectory lost componentwise marker")
        residual = as_float(row, "max_residual_norm")
        terminal_velocity = as_float(row, "max_raw_terminal_endpoint_velocity_constraint_norm")
        ratio = as_float(row, "max_terminal_velocity_vs_scalar_baseline_ratio")
        v.check(residual < 1.0e-8, "paper TFE component-blend trajectory residual too large")
        v.check(1.0e-7 < terminal_velocity < 2.0e-5, "paper TFE component-blend trajectory terminal velocity outside diagnostic range")
        v.check(0.0 < ratio < 1.1, "paper TFE component-blend trajectory scalar-baseline ratio outside diagnostic range")
