        v.check(as_float(row, "max_blend_mean_closure_row_norm") < 1.0e-8, "paper TFE component-blend trajectory mean row too large")
        v.check(as_float(row, "max_source_free_lower_pair_row_norm") < 1.0e-8, "paper TFE component-blend trajectory lower-pair row too large")
