        "stage02_convex_pose_velocity_hscaled_0p00001_pow_m2_z",
        "stage02_convex_pose_velocity_extrapolate_0p00001_0p00002_hpow_m1_z",
        "stage02_convex_pose_velocity_extrapolate_0p00001_0p00002_hpow_m2_z",
        "stage02_convex_pose_velocity_extrapolate_0p00001_0p00002_hpow_m3_z",
