        v.check(audit.get("accepted_h_sweep_present") is False, f"recurrent feedback gain-boundary {label} overclaims accepted h-sweep")
        v.check(audit.get("full_tfe_stage_replacement") is False, f"recurrent feedback gain-boundary {label} overclaims full TFE")
        v.check(float(audit.get("best_terminal_velocity", 1.0)) < 1.0e-12, f"recurrent feedback gain-boundary {label} best terminal velocity changed")
        v.check(float(audit.get("best_terminal_min_order", 99.0)) < 5.0, f"recurrent feedback gain-boundary {label} no longer records terminal-branch order collapse")
        v.check(float(audit.get("best_smooth_order_min_order", 0.0)) > 5.0, f"recurrent feedback gain-boundary {label} no longer records high-order open-terminal endpoint")
        v.check(float(audit.get("best_smooth_order_terminal_velocity", 0.0)) > 1.0e-7, f"recurrent feedback gain-boundary {label} no longer records open terminal velocity on order-preserving branch")


