        v.check(audit.get("feedback_family") == "hscaled_norm_source01historyslope", f"h-scaled recurrent feedback gain-boundary {label} family changed")
        v.check(audit.get("feedback_gains") == expected_gains, f"h-scaled recurrent feedback gain-boundary {label} gain path changed")
        v.check(audit.get("feedback_h_power_values") == expected_h_powers, f"h-scaled recurrent feedback gain-boundary {label} h-power path changed")
        v.check(audit.get("terminal_closed_row_count") == 7, f"h-scaled recurrent feedback gain-boundary {label} terminal closed count changed")
        v.check(audit.get("smooth_order_ok_count") == 0, f"h-scaled recurrent feedback gain-boundary {label} smooth order count changed")
        v.check(audit.get("order_terminal_intersection_present") is False, f"h-scaled recurrent feedback gain-boundary {label} unexpectedly has an order/terminal intersection")
        v.check(audit.get("terminal_closure_requires_order_collapse") is True, f"h-scaled recurrent feedback gain-boundary {label} lost order-collapse marker")
        v.check(audit.get("accepted_h_sweep_present") is False, f"h-scaled recurrent feedback gain-boundary {label} overclaims accepted h-sweep")
        v.check(audit.get("full_tfe_stage_replacement") is False, f"h-scaled recurrent feedback gain-boundary {label} overclaims full TFE")
        v.check(float(audit.get("best_terminal_velocity", 1.0)) < 1.0e-12, f"h-scaled recurrent feedback gain-boundary {label} best terminal velocity changed")
        v.check(float(audit.get("best_terminal_min_order", 99.0)) < 5.0, f"h-scaled recurrent feedback gain-boundary {label} no longer records terminal-branch order collapse")
        v.check(4.6 < float(audit.get("best_smooth_order_min_order", 0.0)) < 4.8, f"h-scaled recurrent feedback gain-boundary {label} best smooth-order row changed")
        v.check(float(audit.get("best_smooth_order_terminal_velocity", 0.0)) > 1.0e-9, f"h-scaled recurrent feedback gain-boundary {label} no longer records open terminal velocity on best-order branch")


