        v.check(2.0e-7 < float(audit.get("best_terminal_velocity", 0.0)) < 2.1e-7, f"recurrent source-law screen {label} best terminal velocity changed")
        v.check(audit.get("best_smooth_order_law") == "recurrent_twohistory_velocity_terminal_source01historyslopecurvature_z", f"recurrent source-law screen {label} best smooth-order law changed")
