def validate_endpoint_tfe_paper_lower_pair_recurrent_source_law_final_retain_boundary(v: Validator) -> None:
    name = "cylindrical_chain_endpoint_tfe_paper_lower_pair_recurrent_source_law_final_retain_boundary_audit.csv"
    rows = v.read_csv(name)
    expected_status = "paper_tfe_lower_pair_recurrent_source_law_final_retain_boundary_tradeoff_not_full_tfe"
    retain_codes = ["p0p000001", "p0p00001", "p0p0001", "p0p001"]
    power_codes = ["p0", "p2"]
    expected_laws = [
        f"recurrent_history_velocity_terminal_finalretainsource_source01historyslope_rel_{retain}_pow_{power}_z"
        for retain in retain_codes
        for power in power_codes
    ] + [
        f"recurrent_twohistory_velocity_terminal_finalretainsource_source01historyslopecurvature_rel_{retain}_pow_{power}_z"
        for retain in retain_codes
        for power in power_codes
    ]
    expected_terminal_closed = [
        "recurrent_history_velocity_terminal_finalretainsource_source01historyslope_rel_p0p000001_pow_p0_z",
        "recurrent_history_velocity_terminal_finalretainsource_source01historyslope_rel_p0p000001_pow_p2_z",
        "recurrent_twohistory_velocity_terminal_finalretainsource_source01historyslopecurvature_rel_p0p000001_pow_p0_z",
        "recurrent_twohistory_velocity_terminal_finalretainsource_source01historyslopecurvature_rel_p0p000001_pow_p2_z",
    ]
    v.check(len(rows) == 16, "recurrent source-law final-retain boundary row count changed")
    actual_laws = [row["predictor_law"] for row in rows]
    v.check(actual_laws == expected_laws, f"recurrent source-law final-retain law list changed: {actual_laws}")
    for row in rows:
        law = row["predictor_law"]
        v.check(row["status"] == expected_status, f"recurrent source-law final-retain status changed for {law}")
        v.check(row["case"] == "cylindrical_smooth", f"recurrent source-law final-retain case changed for {law}")
        v.check(row["h_values"] == "0.04,0.02", f"recurrent source-law final-retain h values changed for {law}")
        v.check(as_float(row, "reference_h") == 0.01, f"recurrent source-law final-retain reference h changed for {law}")
        v.check(as_float(row, "t_final") == 0.04, f"recurrent source-law final-retain t_final changed for {law}")
        v.check(row["reference_completed"] == "True", f"recurrent source-law final-retain reference failed for {law}")
        v.check(row["steps"] == "1,2", f"recurrent source-law final-retain step count changed for {law}")
        v.check(row["source_free_converged_steps"] == "1,2", f"recurrent source-law final-retain convergence changed for {law}")
        v.check(row["endpoint_boundary_source_removed"] == "True", f"recurrent source-law final-retain lost source-free marker for {law}")
        v.check(row["final_stage_velocity_rows_used"] == "True", f"recurrent source-law final-retain lost final-stage-row marker for {law}")
        v.check(row["terminal_row_replacement_used"] == "False", f"recurrent source-law final-retain unexpectedly uses terminal-row replacement for {law}")
        v.check(row["projection_used"] == "False", f"recurrent source-law final-retain unexpectedly uses projection for {law}")
        v.check(row["target_jacobian_used_for_formula"] == "False", f"recurrent source-law final-retain unexpectedly uses target Jacobian for {law}")
        v.check(row["target_direction_oracle_used"] == "False", f"recurrent source-law final-retain unexpectedly uses target direction for {law}")
        v.check(row["accepted_h_sweep_present"] == "False", f"recurrent source-law final-retain overclaims accepted h-sweep for {law}")
        v.check(row["full_tfe_stage_replacement"] == "False", f"recurrent source-law final-retain overclaims full TFE for {law}")
        v.check(int(row["min_jacobian_rank"]) == 132, f"recurrent source-law final-retain rank changed for {law}")
        v.check(int(row["source_consistency_rows"]) == 16, f"recurrent source-law final-retain source rows changed for {law}")
        v.check(int(row["endpoint_pose_velocity_predictor_closure_rows"]) == 8, f"recurrent source-law final-retain closure rows changed for {law}")
        v.check(int(row["source_free_lower_pair_rows"]) == 24, f"recurrent source-law final-retain lower-pair rows changed for {law}")
        v.check(as_float(row, "max_residual_norm") < 1.0e-8, f"recurrent source-law final-retain residual too large for {law}")
        v.check(as_float(row, "min_position_velocity_order") < 5.0, f"recurrent source-law final-retain unexpectedly reaches smooth order for {law}")
        if law.startswith("recurrent_twohistory_velocity_terminal_"):
            v.check(row["source_law_family"] == "two_history_source_law", f"recurrent source-law final-retain two-history family changed for {law}")
            v.check(row["source_law_base"] == "source01historyslopecurvature", f"recurrent source-law final-retain two-history base changed for {law}")
            v.check(int(row["history_source_block_count"]) == 2, f"recurrent source-law final-retain two-history block count changed for {law}")
        else:
            v.check(row["source_law_family"] == "one_history_source_law", f"recurrent source-law final-retain one-history family changed for {law}")
            v.check(row["source_law_base"] == "source01historyslope", f"recurrent source-law final-retain one-history base changed for {law}")
            v.check(int(row["history_source_block_count"]) == 1, f"recurrent source-law final-retain one-history block count changed for {law}")

    terminal_closed_laws = [row["predictor_law"] for row in rows if row["terminal_velocity_closed"] == "True"]
    smooth_order_laws = [row["predictor_law"] for row in rows if row["smooth_order_ok"] == "True"]
    v.check(terminal_closed_laws == expected_terminal_closed, f"recurrent source-law final-retain terminal-closed laws changed: {terminal_closed_laws}")
    v.check(smooth_order_laws == [], f"recurrent source-law final-retain unexpectedly has smooth-order laws: {smooth_order_laws}")
    best_terminal = min(rows, key=lambda row: as_float(row, "max_terminal_velocity"))
    best_order = max(rows, key=lambda row: as_float(row, "min_position_velocity_order"))
    v.check(best_terminal["predictor_law"] == expected_terminal_closed[0], "recurrent source-law final-retain best terminal law changed")
    v.check(as_float(best_terminal, "max_terminal_velocity") < 4.0e-13, "recurrent source-law final-retain best terminal velocity changed")
    v.check(as_float(best_terminal, "min_position_velocity_order") < 5.0, "recurrent source-law final-retain best terminal no longer records order collapse")
    v.check(best_order["predictor_law"] == "recurrent_twohistory_velocity_terminal_finalretainsource_source01historyslopecurvature_rel_p0p001_pow_p2_z", "recurrent source-law final-retain best smooth-order law changed")
    v.check(4.50 < as_float(best_order, "min_position_velocity_order") < 4.52, "recurrent source-law final-retain best smooth order changed")
    v.check(as_float(best_order, "max_terminal_velocity") > 5.0e-10, "recurrent source-law final-retain best-order terminal velocity no longer records open terminal")

    with (RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_recurrent_source_law_final_retain_boundary_audit.json").open() as handle:
        artifact = json.load(handle)
    with (RESULTS / "summary_v047.json").open() as handle:
        summary = json.load(handle)
    summary_audit = summary.get("endpoint_tfe_paper_lower_pair_recurrent_source_law_final_retain_boundary_audit", {})
    for audit, label in [(artifact, "artifact JSON"), (summary_audit, "summary JSON")]:
        v.check(audit.get("status") == expected_status, f"recurrent source-law final-retain {label} status changed")
        v.check(audit.get("row_count") == 16, f"recurrent source-law final-retain {label} row count changed")
        v.check(audit.get("case") == "cylindrical_smooth", f"recurrent source-law final-retain {label} case changed")
        v.check(audit.get("source_law_bases") == ["source01historyslope", "source01historyslopecurvature"], f"recurrent source-law final-retain {label} bases changed")
        v.check(audit.get("retain_values") == [1.0e-6, 1.0e-5, 1.0e-4, 1.0e-3], f"recurrent source-law final-retain {label} retain values changed")
        v.check(audit.get("retain_h_power_values") == [0.0, 2.0], f"recurrent source-law final-retain {label} h powers changed")
        v.check(audit.get("terminal_closed_row_count") == 4, f"recurrent source-law final-retain {label} terminal-closed count changed")
        v.check(audit.get("smooth_order_ok_count") == 0, f"recurrent source-law final-retain {label} smooth-order count changed")
        v.check(audit.get("order_terminal_intersection_present") is False, f"recurrent source-law final-retain {label} unexpectedly has order/terminal intersection")
        v.check(audit.get("terminal_closure_requires_order_collapse") is True, f"recurrent source-law final-retain {label} lost order-collapse marker")
        v.check(audit.get("final_stage_velocity_rows_used") is True, f"recurrent source-law final-retain {label} lost final-stage-row marker")
        v.check(audit.get("accepted_h_sweep_present") is False, f"recurrent source-law final-retain {label} overclaims accepted h-sweep")
        v.check(audit.get("full_tfe_stage_replacement") is False, f"recurrent source-law final-retain {label} overclaims full TFE")
        v.check(audit.get("best_terminal_law") == expected_terminal_closed[0], f"recurrent source-law final-retain {label} best terminal law changed")
        v.check(float(audit.get("best_terminal_velocity", 1.0)) < 4.0e-13, f"recurrent source-law final-retain {label} best terminal velocity changed")
        v.check(float(audit.get("best_terminal_min_order", 10.0)) < 5.0, f"recurrent source-law final-retain {label} best terminal no longer records order collapse")
        v.check(audit.get("best_smooth_order_law") == "recurrent_twohistory_velocity_terminal_finalretainsource_source01historyslopecurvature_rel_p0p001_pow_p2_z", f"recurrent source-law final-retain {label} best smooth-order law changed")
        v.check(4.50 < float(audit.get("best_smooth_order_min_order", 0.0)) < 4.52, f"recurrent source-law final-retain {label} best smooth order changed")
        v.check(float(audit.get("best_smooth_order_terminal_velocity", 0.0)) > 5.0e-10, f"recurrent source-law final-retain {label} best-order terminal velocity no longer records open terminal")


def validate_endpoint_tfe_paper_lower_pair_candidate_frontier(v: Validator) -> None:
    name = "cylindrical_chain_endpoint_tfe_paper_lower_pair_candidate_frontier_audit.csv"
    rows = v.read_csv(name)
    expected_status = "paper_tfe_lower_pair_candidate_frontier_no_intersection_not_full_tfe"
    expected_families = [
        "hscaled_endpoint_pose_velocity_response",
        "recurrent_source_law_trajectory_screen",
        "recurrent_three_history_source_law_screen",
        "recurrent_nonlinear_history_source_law_screen",
        "recurrent_source_law_final_retain_boundary",
        "recurrent_feedback_gain_boundary",
        "recurrent_component_feedback_gain_boundary",
        "recurrent_hscaled_feedback_gain_boundary",
        "source_free_near_final_beta_boundary",
        "source_free_order_closure_blend_trajectory",
        "centered_terminal_velocity_bridge",
    ]
    v.check(len(rows) == 11, "candidate frontier family row count changed")
