    v.check(as_float(by_family["recurrent_source_law_trajectory_screen"], "best_order_terminal_velocity_over_tolerance") > 2.0e5, "candidate frontier recurrent source terminal gap changed")
    v.check(int(by_family["recurrent_source_law_final_retain_boundary"]["terminal_closed_candidate_count"]) == 4, "candidate frontier final-retain terminal count changed")
    v.check(int(by_family["recurrent_source_law_final_retain_boundary"]["smooth_order_candidate_count"]) == 0, "candidate frontier final-retain smooth count changed")
    v.check(int(by_family["recurrent_component_feedback_gain_boundary"]["terminal_closed_candidate_count"]) == 5, "candidate frontier component-feedback terminal count changed")
    v.check(int(by_family["recurrent_component_feedback_gain_boundary"]["smooth_order_candidate_count"]) == 1, "candidate frontier component-feedback smooth count changed")
    v.check(int(by_family["source_free_order_closure_blend_trajectory"]["terminal_closed_candidate_count"]) == 6, "candidate frontier order/closure terminal count changed")
