        v.check(4.50 < float(audit.get("best_terminal_min_order", 0.0)) < 4.52, f"candidate frontier {label} best terminal order changed")
        v.check(audit.get("best_order_family") == "recurrent_source_law_trajectory_screen", f"candidate frontier {label} best order family changed")
        v.check(audit.get("best_order_candidate") == "recurrent_twohistory_velocity_terminal_source01historyslopecurvature_z", f"candidate frontier {label} best order candidate changed")
        v.check(5.34 < float(audit.get("best_order_min_order", 0.0)) < 5.36, f"candidate frontier {label} best order changed")
        v.check(float(audit.get("best_order_terminal_velocity", 0.0)) > 2.0e-7, f"candidate frontier {label} best-order terminal velocity no longer records open terminal")
        v.check(audit.get("accepted_candidate_count") == 0, f"candidate frontier {label} unexpectedly accepts candidates")
        v.check(audit.get("accepted_h_sweep_present") is False, f"candidate frontier {label} overclaims accepted h-sweep")
        v.check(audit.get("full_tfe_stage_replacement") is False, f"candidate frontier {label} overclaims full TFE")
