def validate_endpoint_tfe_paper_lower_pair_bounded_tangent_requirement(v: Validator) -> None:
    name = "cylindrical_chain_endpoint_tfe_paper_lower_pair_bounded_tangent_requirement_audit.csv"
    rows = v.read_csv(name)
    expected_status = "paper_tfe_lower_pair_bounded_tangent_requirement_target_free_gap_not_full_tfe"
    expected_ids = [
        "frontier_order_terminal_intersection",
        "frozen_row_space_compression",
        "coefficient_derivative_oracle",
        "bounded_gradient_cap",
        "bounded_formula_oracle",
        "target_free_bounded_formula",
        "weak_row_structure_capacity",
    ]
    v.check(len(rows) == 7, "bounded tangent requirement row count changed")
    actual_ids = [row["requirement_id"] for row in rows]
    v.check(actual_ids == expected_ids, f"bounded tangent requirement ids changed: {actual_ids}")
    for row in rows:
        rid = row["requirement_id"]
        v.check(row["status"] == expected_status, f"bounded tangent requirement status changed for {rid}")
        v.check(row["source_present"] == "True", f"bounded tangent requirement source missing for {rid}")
        v.check(row["accepted_h_sweep_present"] == "False", f"bounded tangent requirement overclaims h-sweep for {rid}")
        v.check(row["full_tfe_stage_replacement"] == "False", f"bounded tangent requirement overclaims full TFE for {rid}")
        v.check("stage-local weak-row tangent" in row["next_formula_requirement"], f"bounded tangent requirement target changed for {rid}")

    by_id = {row["requirement_id"]: row for row in rows}
    frontier = by_id["frontier_order_terminal_intersection"]
    v.check(int(frontier["observed_count"]) == 0, "bounded tangent frontier intersection count changed")
    v.check(int(frontier["required_count"]) == 1, "bounded tangent frontier required count changed")
    v.check(frontier["target_free"] == "True", "bounded tangent frontier target-free flag changed")
    v.check(frontier["uses_target_direction_oracle"] == "False", "bounded tangent frontier oracle flag changed")

    frozen = by_id["frozen_row_space_compression"]
    v.check(int(frozen["observed_count"]) == 0, "bounded tangent frozen row-space span count changed")
    v.check(int(frozen["required_count"]) == 36, "bounded tangent frozen row-space required count changed")
    v.check(0.7 < as_float(frozen, "best_metric") < 0.8, "bounded tangent frozen row-space residual changed")
    v.check(frozen["target_free"] == "True", "bounded tangent frozen row-space target-free flag changed")

    oracle = by_id["coefficient_derivative_oracle"]
    v.check(int(oracle["observed_count"]) == 36, "bounded tangent oracle span count changed")
    v.check(int(oracle["required_count"]) == 36, "bounded tangent oracle required count changed")
    v.check(as_float(oracle, "best_metric") < 1.0e-12, "bounded tangent oracle residual changed")
    v.check(oracle["uses_target_jacobian"] == "True", "bounded tangent oracle Jacobian flag changed")
    v.check(oracle["uses_target_direction_oracle"] == "True", "bounded tangent oracle direction flag changed")
    v.check(oracle["target_free"] == "False", "bounded tangent oracle target-free flag changed")
    v.check(oracle["bounded"] == "False", "bounded tangent oracle bounded flag changed")

    gradient = by_id["bounded_gradient_cap"]
    v.check(int(gradient["observed_count"]) == 12, "bounded tangent practical cap span count changed")
    v.check(int(gradient["required_count"]) == 36, "bounded tangent practical cap required count changed")
    v.check(as_float(gradient, "best_metric") > 1.0e17, "bounded tangent all-span gradient cap changed")
    v.check(as_float(gradient, "limit_metric") == 1.0e12, "bounded tangent practical cap changed")
    v.check(gradient["target_free"] == "False", "bounded tangent gradient target-free flag changed")
    v.check(gradient["bounded"] == "True", "bounded tangent gradient bounded flag changed")

    formula = by_id["bounded_formula_oracle"]
    v.check(int(formula["observed_count"]) == 366, "bounded tangent bounded-formula span count changed")
    v.check(int(formula["required_count"]) == 648, "bounded tangent bounded-formula required count changed")
    v.check(as_float(formula, "best_metric") > 1.0e21, "bounded tangent bounded-formula cap changed")
    v.check(formula["uses_target_direction_oracle"] == "True", "bounded tangent bounded-formula oracle flag changed")
    v.check(formula["target_free"] == "False", "bounded tangent bounded-formula target-free flag changed")

    target_free = by_id["target_free_bounded_formula"]
    v.check(int(target_free["observed_count"]) == 0, "bounded tangent target-free formula span count changed")
    v.check(int(target_free["required_count"]) == 2592, "bounded tangent target-free formula required count changed")
    v.check(as_float(target_free, "best_metric") > 0.9, "bounded tangent target-free formula residual changed")
    v.check(target_free["target_free"] == "True", "bounded tangent target-free formula flag changed")
    v.check(target_free["bounded"] == "True", "bounded tangent target-free bounded flag changed")

    weak = by_id["weak_row_structure_capacity"]
    v.check(int(weak["observed_count"]) == 0, "bounded tangent weak-row span count changed")
