def validate_endpoint_tfe_paper_lower_pair_recurrent_stage2_feature_dictionary_span(v: Validator) -> None:
    name = "cylindrical_chain_endpoint_tfe_paper_lower_pair_recurrent_stage2_feature_dictionary_span_audit.csv"
    rows = v.read_csv(name)
    span_status = "paper_tfe_lower_pair_recurrent_stage2_feature_dictionary_span_local_capacity_not_full_tfe"
    gap_status = "paper_tfe_lower_pair_recurrent_stage2_feature_dictionary_span_gap_not_full_tfe"
    expected_groups = {
        "scalar_gradient",
        "stage2_matrix_core",
        "stage2_translation_velocity_matrix",
        "stage2_translation_angular_coupled_matrix",
        "combined_matrix_dictionary",
        "combined_all_target_free_dictionary",
    }
    v.check(len(rows) == 12, "stage2 feature dictionary row count changed")
    v.check({row["dictionary_group"] for row in rows} == expected_groups, "stage2 feature dictionary groups changed")
    v.check(
        {row["history_mode"] for row in rows} == {"zero_initial", "post_one_step"},
        "stage2 feature dictionary history modes changed",
    )
    span_rows = [row for row in rows if row["dictionary_spans_terminal_bridge"] == "True"]
    combined_rows = [row for row in rows if row["dictionary_group"] == "combined_all_target_free_dictionary"]
    core_rows = [row for row in rows if row["dictionary_group"] == "stage2_matrix_core"]
    translation_only_rows = [
        row for row in rows if row["dictionary_group"] == "stage2_translation_velocity_matrix"
    ]
    v.check(len(span_rows) == 8, "stage2 feature dictionary span count changed")
    v.check(len(combined_rows) == 2, "stage2 feature dictionary combined row count changed")
    v.check(all(row["dictionary_spans_terminal_bridge"] == "True" for row in combined_rows), "combined dictionary no longer spans")
    v.check(all(row["dictionary_spans_terminal_bridge"] == "True" for row in core_rows), "stage2 matrix core no longer spans")
    v.check(
        all(row["dictionary_spans_terminal_bridge"] == "False" for row in translation_only_rows),
        "translation-only dictionary unexpectedly spans all samples",
    )
    for row in rows:
        spans = row["dictionary_spans_terminal_bridge"] == "True"
        v.check(row["status"] == (span_status if spans else gap_status), "stage2 dictionary status/span mismatch")
        v.check(row["target_free_dictionary"] == "True", "stage2 dictionary target-free flag changed")
