            "stage2_translation_velocity_feature_outer_stage2_velocity",
            "stage2_translation_velocity_stage2_velocity_outer_feature",
            "stage2_translation_velocity_symmetric_stage2_velocity_outer_feature",
            "stage2_translation_velocity_hadamard_diagonal_feature_stage2_velocity",
