            "stage2_velocity_rowmask_angular_from_translation_feature",
            "stage2_velocity_bidirectional_rowmask_translation_angular_feature",
            "stage2_velocity_shifted_bidirectional_rowmask_translation_angular_feature",
            "stage2_velocity_pair_swap_diagonal_feature",
            "stage2_velocity_pair_swap_hadamard_diagonal_feature_stage2_velocity",
            "stage2_velocity_pair_swap_outer_stage2_velocity",
            "stage2_velocity_stage2_velocity_outer_pair_swap_feature",
            "stage2_velocity_symmetric_pair_swap_outer_stage2_velocity",
            "stage2_velocity_local_pair_cross_feature",
            "stage2_velocity_local_pair_swap_stage2_velocity_cross_feature",
            "stage2_velocity_pair_swap_stage2_hadamard_row_feature",
