    with (RESULTS / "cylindrical_chain_endpoint_tfe_paper_lower_pair_recurrent_stage2_translation_angular_coupled_matrix_differential_audit.json").open() as handle:
        coupled_matrix_artifact = json.load(handle)
    with (RESULTS / "summary_v047.json").open() as handle:
        summary = json.load(handle)
