    matrix_summary = summary.get("endpoint_tfe_paper_lower_pair_recurrent_stage2_matrix_gradient_differential_audit", {})
    translation_matrix_summary = summary.get("endpoint_tfe_paper_lower_pair_recurrent_stage2_translation_velocity_matrix_differential_audit", {})
