        by_candidate[candidate] += 1
        by_feature[feature] += 1
        spans = row["direction_capacity_spans_target"] == "True"
        if spans:
            spans_by_feature[feature] += 1
            if row["uses_final_stage_velocity_feature"] == "False":
                nonfinal_span_count += 1
        expected_training = 1 if candidate.startswith("case_local_") else 6
        expected_scope = "case_local_direction_capacity_oracle_fit" if candidate.startswith("case_local_") else "all_case_h_direction_capacity_oracle_fit"
