def validate_endpoint_tfe_paper_lower_pair_velocity_compression_row_space_compression(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_paper_lower_pair_velocity_compression_row_space_compression_audit.csv")
    expected_laws = {
        "all_stage_svd_top8",
        "nonfinal_svd_top8",
        "all_stage_row_norm_top8",
        "nonfinal_row_norm_top8",
        "stage_balanced_norm_all_stage",
        "stage_balanced_norm_nonfinal",
    }
    expected_by_law = {
        "all_stage_svd_top8": ("0,1,2", 24, True, "all_stage_velocity_row_space", False),
        "nonfinal_svd_top8": ("0,1", 16, False, "nonfinal_stage_velocity_row_space", False),
        "all_stage_row_norm_top8": ("0,1,2", 8, True, "all_stage_velocity_row_norm_selector", True),
        "nonfinal_row_norm_top8": ("0,1", 8, False, "nonfinal_stage_velocity_row_norm_selector", True),
        "stage_balanced_norm_all_stage": ("1", 8, False, "componentwise_all_stage_row_norm_selector", True),
        "stage_balanced_norm_nonfinal": ("1", 8, False, "componentwise_nonfinal_row_norm_selector", True),
    }
    by_law = {law: 0 for law in expected_laws}
    law_names = {row["row_space_compression_law"] for row in rows}
    v.check(law_names == expected_laws, f"row-space compression laws changed: {sorted(law_names)}")
    for row in rows:
        law = row["row_space_compression_law"]
        by_law[law] += 1
        active_stages, active_velocity_rows, uses_final, source, has_selected_indices = expected_by_law[law]
        v.check(row["candidate_basis"] == law, f"row-space compression candidate/law mismatch for {law}")
        v.check(row["fit_scope"] == "case_local_target_free_row_space_compression", f"row-space compression fit scope changed for {law}")
        v.check(row["candidate_kind"] == "target_free_frozen_row_space_compression", f"row-space compression kind changed for {law}")
        v.check(row["active_stage_rows"] == active_stages, f"row-space compression active stages changed for {law}")
        v.check(int(row["training_sample_count"]) == 1, f"row-space compression training sample count changed for {law}")
        v.check(int(row["basis_row_count"]) == 24, f"row-space compression basis row count changed for {law}")
        v.check(int(row["compression_row_count"]) == 8, f"row-space compression compression row count changed for {law}")
        v.check(int(row["source_consistency_rows"]) == 16, f"row-space compression source row count changed for {law}")
        v.check(int(row["velocity_stage_rows"]) == 24, f"row-space compression velocity row count changed for {law}")
        v.check(int(row["active_velocity_rows"]) == active_velocity_rows, f"row-space compression active velocity rows changed for {law}")
        v.check(int(row["target_row_count"]) == 8, f"row-space compression target row count changed for {law}")
        v.check(row["row_space_source"] == source, f"row-space compression source changed for {law}")
        v.check(int(row["row_space_candidate_rows"]) == 8, f"row-space compression candidate rows changed for {law}")
        v.check(0 <= int(row["row_space_candidate_rank"]) <= 8, f"row-space compression candidate rank invalid for {law}")
        if has_selected_indices:
            selected = [part for part in row["selected_velocity_indices"].split(",") if part]
            v.check(len(selected) == 8, f"row-space compression selected-index count changed for {law}")
        else:
            v.check(row["selected_velocity_indices"] == "", f"row-space compression SVD selected indices unexpectedly present for {law}")
        v.check(row["uses_final_stage_velocity_feature"] == str(uses_final), f"row-space compression final-stage marker changed for {law}")
        v.check(row["target_jacobian_used_for_formula"] == "False", f"row-space compression unexpectedly uses target Jacobian for {law}")
        v.check(row["target_direction_oracle_used"] == "False", f"row-space compression unexpectedly uses target direction for {law}")
        v.check(row["frozen_state_dependent_coefficients"] == "True", f"row-space compression lost frozen coefficient marker for {law}")
        v.check(row["coefficient_derivative_included"] == "False", f"row-space compression unexpectedly includes coefficient derivative for {law}")
        v.check(row["endpoint_boundary_source_removed"] == "True", f"row-space compression lost source-free marker for {law}")
        v.check(row["target_terminal_boundary_row_used"] == "True", f"row-space compression lost target terminal-boundary marker for {law}")
        v.check(row["terminal_row_replacement_used"] == "False", f"row-space compression unexpectedly uses terminal-row replacement for {law}")
        v.check(row["projection_used"] == "False", f"row-space compression unexpectedly uses projection for {law}")
        v.check(row["accepted_h_sweep_present"] == "False", f"row-space compression overclaims accepted h-sweep for {law}")
        v.check(row["full_tfe_stage_replacement"] == "False", f"row-space compression overclaims full TFE for {law}")
        v.check(row["row_space_compression_spans_target"] == "False", f"row-space compression unexpectedly spans for {law}")
        v.check(row["status"] in {
            "paper_tfe_lower_pair_velocity_compression_row_space_compression_spans_not_full_tfe",
            "paper_tfe_lower_pair_velocity_compression_row_space_compression_gap_not_full_tfe",
        }, f"row-space compression status changed for {law}")
        v.check(math.isfinite(as_float(row, "projection_relative_residual")), f"row-space compression projection residual is not finite for {law}")
        v.check(math.isfinite(as_float(row, "value_residual_norm")), f"row-space compression value residual is not finite for {law}")
        v.check(math.isfinite(as_float(row, "coefficient_norm")), f"row-space compression coefficient norm is not finite for {law}")
    for law, count in by_law.items():
        v.check(count == 6, f"row-space compression law {law} row count changed")


def validate_endpoint_tfe_paper_lower_pair_velocity_compression_row_space_coefficient_derivative(v: Validator) -> None:
    rows = v.read_csv(
        "cylindrical_chain_endpoint_tfe_paper_lower_pair_velocity_compression_row_space_coefficient_derivative_audit.csv"
    )
    with (
        RESULTS
        / "cylindrical_chain_endpoint_tfe_paper_lower_pair_velocity_compression_row_space_coefficient_derivative_audit.json"
    ).open() as handle:
        artifact = json.load(handle)
    expected_laws = {
        "all_stage_svd_top8",
        "nonfinal_svd_top8",
        "all_stage_row_norm_top8",
        "nonfinal_row_norm_top8",
        "stage_balanced_norm_all_stage",
        "stage_balanced_norm_nonfinal",
    }
    expected_by_law = {
        "all_stage_svd_top8": ("0,1,2", 24, True, "all_stage_velocity_row_space", False),
        "nonfinal_svd_top8": ("0,1", 16, False, "nonfinal_stage_velocity_row_space", False),
        "all_stage_row_norm_top8": ("0,1,2", 8, True, "all_stage_velocity_row_norm_selector", True),
        "nonfinal_row_norm_top8": ("0,1", 8, False, "nonfinal_stage_velocity_row_norm_selector", True),
        "stage_balanced_norm_all_stage": ("1", 8, False, "componentwise_all_stage_row_norm_selector", True),
        "stage_balanced_norm_nonfinal": ("1", 8, False, "componentwise_nonfinal_row_norm_selector", True),
    }
    v.check(artifact.get("row_count") == 36, "row-space coefficient-derivative artifact row count changed")
    v.check(artifact.get("spanning_row_count") == 36, "row-space coefficient-derivative artifact span count changed")
    v.check(artifact.get("value_balanced_spanning_row_count") == 24, "row-space coefficient-derivative value-balanced span count changed")
    v.check(artifact.get("target_direction_oracle_used") is True, "row-space coefficient-derivative artifact lost oracle marker")
    v.check(artifact.get("coefficient_derivative_included") is True, "row-space coefficient-derivative artifact lost derivative marker")
    v.check(artifact.get("full_tfe_stage_replacement") is False, "row-space coefficient-derivative artifact overclaims full TFE")
    v.check(len(artifact.get("rows", [])) == len(rows), "row-space coefficient-derivative JSON/CSV row count mismatch")
    law_names = {row["row_space_compression_law"] for row in rows}
    v.check(law_names == expected_laws, f"row-space coefficient-derivative laws changed: {sorted(law_names)}")
    by_law = {law: 0 for law in expected_laws}
    value_ok_count = 0
    span_count = 0
    status_counts = {
        "paper_tfe_lower_pair_velocity_compression_row_space_coefficient_derivative_oracle_spans_not_full_tfe": 0,
        "paper_tfe_lower_pair_velocity_compression_row_space_coefficient_derivative_value_gap_not_full_tfe": 0,
    }
    for row in rows:
        law = row["row_space_compression_law"]
        by_law[law] += 1
        active_stages, active_velocity_rows, uses_final, source, has_selected_indices = expected_by_law[law]
        value_ok_count += int(row["value_level_balance_ok"] == "True")
        span_count += int(row["row_space_coefficient_derivative_spans_target"] == "True")
        if row["status"] in status_counts:
            status_counts[row["status"]] += 1
        v.check(row["candidate_basis"] == law, f"row-space coefficient-derivative candidate/law mismatch for {law}")
        v.check(row["fit_scope"] == "case_local_row_space_coefficient_derivative_oracle", f"row-space coefficient-derivative fit scope changed for {law}")
        v.check(row["candidate_kind"] == "target_free_row_space_compression_with_target_oracle_coefficient_derivative", f"row-space coefficient-derivative kind changed for {law}")
        v.check(row["active_stage_rows"] == active_stages, f"row-space coefficient-derivative active stages changed for {law}")
        v.check(int(row["training_sample_count"]) == 1, f"row-space coefficient-derivative training sample count changed for {law}")
        v.check(int(row["basis_row_count"]) == 24, f"row-space coefficient-derivative basis row count changed for {law}")
        v.check(int(row["compression_row_count"]) == 8, f"row-space coefficient-derivative compression row count changed for {law}")
        v.check(int(row["source_consistency_rows"]) == 16, f"row-space coefficient-derivative source row count changed for {law}")
        v.check(int(row["velocity_stage_rows"]) == 24, f"row-space coefficient-derivative velocity row count changed for {law}")
        v.check(int(row["active_velocity_rows"]) == active_velocity_rows, f"row-space coefficient-derivative active velocity rows changed for {law}")
        v.check(int(row["target_row_count"]) == 8, f"row-space coefficient-derivative target row count changed for {law}")
        v.check(row["row_space_source"] == source, f"row-space coefficient-derivative source changed for {law}")
        v.check(int(row["row_space_candidate_rows"]) == 8, f"row-space coefficient-derivative candidate rows changed for {law}")
        v.check(0 <= int(row["row_space_candidate_rank"]) <= 8, f"row-space coefficient-derivative candidate rank invalid for {law}")
        if has_selected_indices:
            selected = [part for part in row["selected_velocity_indices"].split(",") if part]
            v.check(len(selected) == 8, f"row-space coefficient-derivative selected-index count changed for {law}")
        else:
            v.check(row["selected_velocity_indices"] == "", f"row-space coefficient-derivative SVD selected indices unexpectedly present for {law}")
        v.check(row["uses_final_stage_velocity_feature"] == str(uses_final), f"row-space coefficient-derivative final-stage marker changed for {law}")
        v.check(row["target_jacobian_used_for_formula"] == "True", f"row-space coefficient-derivative lost target-Jacobian marker for {law}")
        v.check(row["target_direction_oracle_used"] == "True", f"row-space coefficient-derivative lost target-direction marker for {law}")
        v.check(row["frozen_state_dependent_coefficients"] == "False", f"row-space coefficient-derivative unexpectedly keeps frozen coefficient marker for {law}")
        v.check(row["coefficient_derivative_included"] == "True", f"row-space coefficient-derivative lost derivative marker for {law}")
        v.check(row["endpoint_boundary_source_removed"] == "True", f"row-space coefficient-derivative lost source-free marker for {law}")
        v.check(row["target_terminal_boundary_row_used"] == "True", f"row-space coefficient-derivative lost target terminal-boundary marker for {law}")
        v.check(row["terminal_row_replacement_used"] == "False", f"row-space coefficient-derivative unexpectedly uses terminal-row replacement for {law}")
        v.check(row["projection_used"] == "False", f"row-space coefficient-derivative unexpectedly uses projection for {law}")
        v.check(row["accepted_h_sweep_present"] == "False", f"row-space coefficient-derivative overclaims accepted h-sweep for {law}")
        v.check(row["full_tfe_stage_replacement"] == "False", f"row-space coefficient-derivative overclaims full TFE for {law}")
        v.check(row["row_space_coefficient_derivative_spans_target"] == "True", f"row-space coefficient-derivative unexpectedly fails span for {law}")
        v.check(as_float(row, "projection_relative_residual") < 1.0e-12, f"row-space coefficient-derivative residual changed for {law}")
        v.check(0.7 < as_float(row, "base_projection_relative_residual") or law != "all_stage_svd_top8", f"row-space coefficient-derivative base residual changed for {law}")
        v.check(math.isfinite(as_float(row, "required_coefficient_gradient_fro_norm")), f"row-space coefficient-derivative gradient norm is not finite for {law}")
        v.check(math.isfinite(as_float(row, "value_residual_norm")), f"row-space coefficient-derivative value residual is not finite for {law}")
    for law, count in by_law.items():
        v.check(count == 6, f"row-space coefficient-derivative law {law} row count changed")
    v.check(span_count == 36, "row-space coefficient-derivative span count changed")
    v.check(value_ok_count == 24, "row-space coefficient-derivative value-ok count changed")
    v.check(status_counts["paper_tfe_lower_pair_velocity_compression_row_space_coefficient_derivative_oracle_spans_not_full_tfe"] == 24, "row-space coefficient-derivative oracle status count changed")
    v.check(status_counts["paper_tfe_lower_pair_velocity_compression_row_space_coefficient_derivative_value_gap_not_full_tfe"] == 12, "row-space coefficient-derivative value-gap status count changed")


def validate_endpoint_tfe_paper_residual_substitution_contract(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_paper_residual_substitution_contract_audit.csv")
    by_component = {row["component"]: row for row in rows}
    expected = {
        "translational_position_weak_defect": (6, 18, "x_q,y_q", "stage_local_position_defect_weak_row", False, True),
        "rotational_lie_position_weak_defect": (6, 18, "x_q,y_q", "stage_local_lie_position_defect_weak_row", False, True),
        "translational_velocity_weak_defect": (6, 18, "y_q,z_q", "stage_local_velocity_defect_weak_row", False, True),
        "angular_velocity_weak_defect": (6, 18, "y_q,z_q", "stage_local_angular_velocity_defect_weak_row", False, True),
        "newton_euler_weak_balance": (12, 36, "x_q,y_q,z_q,lambda_x", "stage_local_newton_euler_weak_balance_row", True, True),
        "lower_pair_index3_weak_constraints": (8, 24, "x_q,y_q,z_q", "stage_local_lower_pair_index3_weak_constraint_row", False, True),
    }
    v.check(set(by_component) == set(expected), f"paper TFE residual-substitution contract components mismatch: {sorted(by_component)}")
    total = 0
    for component, (rows_per_stage, total_rows, inputs, target, multiplier_required, formula_present) in expected.items():
        row = by_component.get(component, {})
        expected_substituted = True
        expected_status = "paper_tfe_residual_substitution_all_row_substituted_order_limited_diagnostic_z0"
        total += int(row.get("total_rows", 0) or 0)
        v.check(row.get("status") == expected_status, f"paper TFE residual-substitution contract status changed for {component}")
        v.check(int(row.get("rows_per_stage", -1)) == rows_per_stage, f"paper TFE residual-substitution rows/stage changed for {component}")
        v.check(int(row.get("total_rows", -1)) == total_rows, f"paper TFE residual-substitution total rows changed for {component}")
        v.check(row.get("paper_inputs_required") == inputs, f"paper TFE residual-substitution inputs changed for {component}")
        v.check(row.get("paper_inputs_mapped") == "True", f"paper TFE residual-substitution inputs not mapped for {component}")
        v.check(row.get("multiplier_policy_required") == str(multiplier_required), f"paper TFE residual-substitution multiplier requirement changed for {component}")
        v.check(row.get("multiplier_policy_satisfied") == "True", f"paper TFE residual-substitution multiplier policy not satisfied for {component}")
        v.check(row.get("stage_local_target") == target, f"paper TFE residual-substitution target changed for {component}")
        v.check(row.get("stage_local_target_mapped") == "True", f"paper TFE residual-substitution target not mapped for {component}")
        v.check(row.get("endpoint_boundary_source_removed") == "False", f"paper TFE residual-substitution overclaims source removal for {component}")
        v.check(row.get("derived_paper_formula_present") == str(formula_present), f"paper TFE residual-substitution formula flag changed for {component}")
        v.check(row.get("residual_substituted") == str(expected_substituted), f"paper TFE residual-substitution substitution flag changed for {component}")
        v.check(row.get("accepted_h_sweep_present") == "False", f"paper TFE residual-substitution overclaims accepted h-sweep for {component}")
        v.check(row.get("full_tfe_stage_replacement") == "False", f"paper TFE residual-substitution overclaims full replacement for {component}")
        v.check("order-limited" in row.get("blocking_gap", ""), f"paper TFE residual-substitution substituted row gap incomplete for {component}")
        v.check("diagnostic z0" in row.get("blocking_gap", ""), f"paper TFE residual-substitution substituted row z0 caveat incomplete for {component}")
    v.check(total == 132, f"paper TFE residual-substitution contract row budget changed: {total}")


def validate_endpoint_tfe_candidate(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_candidate_audit.csv")
    by_case: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
        v.check(row["endpoint_node_weighted_residual_rows_present"] == "True", "TFE candidate row does not record endpoint-node rows")
        v.check(row["stage_equations_are_tfe_weighted"] == "False", "TFE candidate unexpectedly claims weighted stage equations")
        v.check(as_float(row, "candidate_weighted_residual_norm") >= 0.0, "TFE candidate residual is negative")
        v.check(math.isfinite(as_float(row, "candidate_weighted_residual_norm")), "TFE candidate residual is not finite")
        v.check(math.isfinite(as_float(row, "weighted_endpoint_node_residual_norm")), "TFE endpoint-node residual is not finite")
    v.check(set(by_case) == {"cylindrical_smooth", "cylindrical_sharp"}, f"TFE candidate cases mismatch: {sorted(by_case)}")
    for case, case_rows in by_case.items():
        hs = sorted(as_float(row, "h") for row in case_rows)
        v.check(hs == [0.01, 0.02, 0.04], f"TFE candidate h sweep mismatch for {case}: {hs}")
        statuses = {row["status"] for row in case_rows}
        v.check(statuses == {"candidate_rows_generated_not_full_tfe"}, f"TFE candidate status mismatch for {case}: {sorted(statuses)}")


def validate_endpoint_tfe_solved_candidate(v: Validator) -> None:
    rows = v.read_csv("cylindrical_chain_endpoint_tfe_solved_candidate_audit.csv")
    by_case: dict[str, list[dict[str, str]]] = {}
    for row in rows:
        by_case.setdefault(row["case"], []).append(row)
