def validate_summary(v: Validator) -> None:
    with (RESULTS / "summary_v047.json").open() as handle:
        summary = json.load(handle)
    v.check(summary.get("version") == "v047_cylindrical_chain_pipeline", "summary version is not v047_cylindrical_chain_pipeline")
    v.check(summary.get("asme_gate", {}).get("status") == "four_asme_method_rows_accepted_projection_sharp_sparse_caveats", "ASME gate summary status changed")
    v.check(summary.get("endpoint_kkt_closure", {}).get("status") == "ok", "endpoint KKT summary status is not ok")
    v.check(summary.get("endpoint_tfe_gap_audit", {}).get("status") == "ok_gap_quantified_not_tfe", "endpoint TFE gap summary status is not ok_gap_quantified_not_tfe")
