def validate_docs(v: Validator) -> None:
    readme = (ROOT / "README.md").read_text()
    report = (RESULTS / "v047_report.md").read_text()
    tick = "`"
    readme_listed = {
        item.removeprefix("results/")
        for item in re.findall(tick + r"(results/[^`]+)" + tick, readme)
    }
    report_listed = set(re.findall(tick + r"([^`]+\.(?:csv|png|json))" + tick, report))
    expected = set(EXPECTED_RESULTS)
    v.check(readme_listed == expected, f"README generated-output list mismatch: missing={sorted(expected - readme_listed)} extra={sorted(readme_listed - expected)}")
    v.check(report_listed == expected - {"v047_report.md"}, f"report output list mismatch: missing={sorted((expected - {'v047_report.md'}) - report_listed)} extra={sorted(report_listed - expected)}")

    docs = [
        WORK / "README.md",
        WORK / "VERSION_LEDGER.md",
        WORK / "VERSION_TREE.md",
        WORK / "PIPELINE_AUDIT.md",
        WORK / "ORDER_PROOF_LEDGER.md",
        WORK / "version_ledger.csv",
        ROOT / "README.md",
        RESULTS / "v047_report.md",
    ]
    for path in docs:
        text = path.read_text()
        for pattern in STALE_PATTERNS:
            v.check(not re.search(pattern, text), f"stale pattern {pattern!r} found in {path.relative_to(WORK)}")


